window.KHO_DATA_L1_MITHUAT = [
{"lop":1,"mon":"Mĩ thuật","tuan":1,"tiet":1,"bai":"Chủ đề 1: Mĩ thuật trong nhà trường (Tiết 1)","yccd":"1. Năng lực mĩ thuật\n- Nhận biết được mĩ thuật có ở xung quanh và được tạo bởi những người khác nhau, nhất là học sinh trong nhà trường.\n- Kể được tên một số sản phẩm mĩ thuật đã làm hoặc đã thấy trong nhà trường.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động quan sát, kể lại hiểu biết của mình về sản phẩm mĩ thuật.\n- Giao tiếp và hợp tác: Trao đổi với bạn, lắng nghe ý kiến khi tìm hiểu bài.\n3. Phẩm chất\n- Chăm chỉ: Hào hứng tham gia hoạt động học tập.\n- Yêu nước: Yêu thích cái đẹp có ở trường lớp, quê hương.\n4. Tích hợp\n- Năng lực số 1.2 CB1 (Đánh giá dữ liệu, thông tin và nội dung số): HS gọi tên được các sản phẩm mĩ thuật trong trường qua ảnh chiếu phóng to.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 1; một số hình ảnh, clip sản phẩm mĩ thuật trình chiếu trên máy chiếu (nếu có); một số sản phẩm mĩ thuật thật để HS quan sát.\n- Học sinh: Sách Mĩ thuật lớp 1, Vở thực hành Mĩ thuật lớp 1, đồ dùng học tập trong môn học.","hoatdong":[{"ten":"1. Khởi động","gv":"Mục tiêu: Tạo tâm thế vui vẻ, khơi gợi hứng thú với môn Mĩ thuật.\n- GV cho HS xem nhanh một vài bức tranh, sản phẩm đẹp và hỏi: “Các em thấy những hình này có đẹp không? Ai đã làm ra chúng?”\n- GV dẫn vào bài: “Hôm nay chúng ta cùng tìm hiểu mĩ thuật có ở quanh ta trong nhà trường.”","hs":"- HS quan sát, nêu cảm nhận: đẹp, nhiều màu sắc.\n- HS trả lời theo suy nghĩ: do các bạn, các anh chị, thầy cô làm.\n- HS lắng nghe, nhắc lại tên bài."},{"ten":"2. Khám phá - Sản phẩm mĩ thuật quanh em","gv":"Mục tiêu: Nhận biết được các sản phẩm mĩ thuật có trong sách và trong nhà trường.\n- GV cho HS mở SGK, quan sát các sản phẩm mĩ thuật và trình bày hiểu biết của mình.\n- GV hỏi: “Em thấy sản phẩm nào? Sản phẩm đó làm bằng gì?”\n- GV giải thích trên cơ sở ý kiến của HS, chỉ giới thiệu chứ chưa đi sâu vào chất liệu, cách làm.","hs":"- HS quan sát sách, trình bày hiểu biết về những sản phẩm mĩ thuật.\n- HS trả lời: tranh vẽ, tượng nặn, sản phẩm trang trí…\n- HS lắng nghe và đặt câu hỏi khi chưa hiểu."},{"ten":"3. Luyện tập - Kể tên sản phẩm mĩ thuật","gv":"Mục tiêu: Củng cố kiến thức, HS kể được sản phẩm mĩ thuật đã làm hoặc đã thấy.\n- GV yêu cầu HS kể tên một số sản phẩm mĩ thuật mình đã làm hoặc đã thấy trong nhà trường.\n- GV khích lệ HS nói theo trí nhớ và quan sát thực tế lớp học.","hs":"- HS kể: tranh vẽ, đồ trang trí lớp, sản phẩm nặn, xé dán…\n- HS lắng nghe bạn và bổ sung ý kiến."},{"ten":"4. Vận dụng - Tìm cái đẹp trong lớp học","gv":"Mục tiêu: Liên hệ mĩ thuật với môi trường quanh em.\n- GV cho HS quan sát lớp học, tìm những chỗ được trang trí đẹp.\n- GV nhận xét tiết học, khen ngợi HS.","hs":"- HS chỉ ra góc trang trí, bảng, tranh ảnh trong lớp.\n- HS lắng nghe."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu bộ ảnh chụp các sản phẩm mĩ thuật có thật trong trường: tranh trên bảng tin, hình trang trí lớp học, tượng và bồn hoa ở sân trường; ảnh được phóng to nên HS nhìn rõ nét vẽ, màu sắc mà lúc chạy ngoài sân không để ý thấy.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) GV mời HS lần lượt chỉ vào ảnh trên màn hình và nói “Em thích chỗ này vì…”; nếu ảnh đó là sản phẩm của một bạn trong lớp thì HS tập nói lời khen trực tiếp với bạn.\n⚠ (Miền 4: An toàn) Ảnh chụp trong trường chỉ dùng để học, GV giữ trong máy của mình, không đưa lên mạng; HS ngồi tại chỗ nhìn màn hình, xem một lúc thì nhìn ra cửa sổ cho đỡ mỏi mắt.","hs":"- HS gọi tên được các sản phẩm mĩ thuật trong trường qua ảnh chiếu phóng to.\n- HS nói được lời khen cụ thể về sản phẩm mình thích."}],"status":"checked","source":"KHBD Mĩ thuật 1 KNTT (Bút Xanh) — Chủ đề 1, Tiết 1"},
{"lop":1,"mon":"Mĩ thuật","tuan":2,"tiet":2,"bai":"Chủ đề 1: Mĩ thuật trong nhà trường (Tiết 2)","yccd":"1. Năng lực mĩ thuật\n- Nhận biết được một số đồ dùng, công cụ, vật liệu để thực hành, sáng tạo trong môn học.\n- Bước đầu biết cách bảo quản, sử dụng một số đồ dùng học tập.\n2. Năng lực chung\n- Tự chủ và tự học: Tự chuẩn bị và giữ gìn đồ dùng học tập.\n- Giải quyết vấn đề và sáng tạo: Biết chọn đồ dùng phù hợp với việc thực hành.\n3. Phẩm chất\n- Trách nhiệm: Giữ gìn, bảo quản đồ dùng học tập gọn gàng, sạch sẽ.\n- Chăm chỉ: Chuẩn bị đầy đủ đồ dùng học tập.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 1; một số vật dụng, đồ dùng sử dụng trong môn Mĩ thuật; đồ dùng học tập từ vật liệu tái sử dụng; máy chiếu (nếu có).\n- Học sinh: Sách Mĩ thuật lớp 1, Vở thực hành Mĩ thuật lớp 1, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"Mục tiêu: Tạo hứng thú, dẫn dắt tới đồ dùng học môn Mĩ thuật.\n- GV cho HS chơi trò “Chiếc túi kì diệu”: lần lượt lấy ra bút chì, sáp màu, giấy màu… và hỏi tên.\n- GV dẫn vào bài về đồ dùng trong môn học.","hs":"- HS đoán tên đồ dùng khi thấy hoặc chạm vào.\n- HS lắng nghe, nhắc lại tên bài."},{"ten":"2. Khám phá - Đồ dùng trong môn học","gv":"Mục tiêu: Nhận biết đồ dùng, công cụ, vật liệu và cách sử dụng.\n- GV nêu câu hỏi: “Học môn Mĩ thuật cần những đồ dùng gì? Dùng như thế nào?”\n- GV giới thiệu các dạng màu: màu sáp, màu nước, màu bột, giấy, đất nặn, kéo an toàn…\n- GV lưu ý HS cách sử dụng an toàn (dùng kéo, giữ vệ sinh khi dùng màu).","hs":"- HS kể và chỉ các đồ dùng của mình: bút chì, sáp màu, giấy, đất nặn…\n- HS lắng nghe cách sử dụng và bảo quản đồ dùng.\n- HS đặt câu hỏi khi chưa hiểu."},{"ten":"3. Luyện tập - Thực hành với Vở bài tập","gv":"Mục tiêu: Làm quen với đồ dùng qua thực hành nhẹ nhàng.\n- GV yêu cầu HS mở Vở bài tập Mĩ thuật lớp 1, trang 4–5, làm theo hướng dẫn.\n- GV quan sát, hỗ trợ HS cách cầm bút, dùng màu.","hs":"- HS thực hành theo hướng dẫn trong Vở bài tập.\n- HS tập cầm bút, tô màu đúng cách."},{"ten":"4. Vận dụng - Sắp xếp đồ dùng gọn gàng","gv":"Mục tiêu: Biết bảo quản, sắp xếp đồ dùng học tập.\n- GV hướng dẫn HS sắp xếp đồ dùng vào hộp/túi gọn gàng sau khi học.\n- GV nhận xét tiết học, dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS sắp xếp đồ dùng gọn gàng, sạch sẽ.\n- HS lắng nghe và ghi nhớ."}],"status":"checked","source":"KHBD Mĩ thuật 1 KNTT (Bút Xanh) — Chủ đề 1, Tiết 2"},
{"lop":1,"mon":"Mĩ thuật","tuan":3,"tiet":3,"bai":"Chủ đề 2: Sáng tạo từ những chấm màu (Tiết 1)","yccd":"1. Năng lực mĩ thuật\n- Nhận biết được chấm xuất hiện trong tự nhiên và trong sản phẩm mĩ thuật.\n- Tạo được chấm bằng nhiều cách khác nhau (từ hạt, vật liệu tự nhiên).\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động quan sát, tìm chấm trong tự nhiên.\n- Giải quyết vấn đề và sáng tạo: Biết dùng vật liệu sẵn có để tạo chấm.\n3. Phẩm chất\n- Chăm chỉ: Tích cực thực hành.\n- Trách nhiệm: Giữ vệ sinh khi sử dụng vật liệu.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nhận ra tranh được tạo nên từ nhiều chấm màu nhỏ khi xem ảnh phóng to.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 1; một số hình ảnh về chấm trong cuộc sống; máy chiếu (nếu có); một số loại hạt phổ biến ở địa phương, keo sữa.\n- Học sinh: Sách và Vở thực hành Mĩ thuật lớp 1, đồ dùng học tập; hạt, vật liệu tự nhiên có dạng chấm; giấy A4.","hoatdong":[{"ten":"1. Khởi động","gv":"Mục tiêu: Khơi gợi sự chú ý đến chấm quanh em.\n- GV cho HS quan sát một vài hình có chấm (bọ rùa, quả dâu, bầu trời sao) và hỏi: “Em thấy gì trên hình này?”\n- GV dẫn vào bài về chấm màu.","hs":"- HS quan sát và trả lời: có nhiều chấm nhỏ.\n- HS lắng nghe, nhắc lại tên bài."},{"ten":"2. Khám phá - Chấm màu trong tự nhiên","gv":"Mục tiêu: Nhận biết sự xuất hiện của chấm trong tự nhiên.\n- GV đặt câu hỏi giúp HS quan sát và nhận biết chấm trong tự nhiên có nhiều hình dạng, màu sắc.\n- GV giải thích thêm về chấm gần gũi với HS ở địa phương (hạt, đốm trên lá, cánh hoa…).","hs":"- HS trình bày hiểu biết về sự xuất hiện của chấm trong tự nhiên.\n- HS lắng nghe và đặt câu hỏi khi chưa hiểu."},{"ten":"3. Luyện tập - Sáng tạo: Tạo chấm từ hạt","gv":"Mục tiêu: Tạo được chấm từ hạt, vật liệu tự nhiên.\n- GV yêu cầu HS thực hành tạo chấm bằng hạt theo các cách khác nhau trên miếng bìa/giấy A4.\n- Mức độ cần đạt: Bắt buộc: tạo được vài chấm; Khuyến khích: xếp chấm tạo thành mảng/hình.","hs":"- HS thực hành dùng vật liệu đã chuẩn bị để tạo chấm.\n- HS xếp chấm thành mảng, hình theo ý thích."},{"ten":"4. Vận dụng - Tìm chấm quanh em","gv":"Mục tiêu: Liên hệ chấm với đồ vật quanh em.\n- GV cho HS tìm những đồ vật, trang phục có chấm trong lớp học.\n- GV nhận xét, khen ngợi.","hs":"- HS chỉ ra áo chấm bi, khăn, đồ vật có chấm.\n- HS lắng nghe."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu ảnh phóng to một bức tranh chấm màu và một tấm vải hoa văn chấm, phóng to dần từng vùng để HS thấy cả bức tranh được tạo bởi rất nhiều chấm nhỏ đặt cạnh nhau — điều nhìn tranh in trong sách khó nhận ra.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 1) GV gõ vào một công cụ vẽ bằng trí tuệ nhân tạo câu “bông hoa vẽ bằng các chấm màu” cho cả lớp cùng xem máy vẽ ra hình gì; GV nói rõ hình này do máy vẽ, không phải của cô, cũng không phải của các em.\n⚠ (Miền 4: An toàn) Chỉ cô giáo gõ chữ và bấm máy, các em ngồi xem; hình do máy vẽ chỉ để xem cho biết, không chép lại thành bài của mình vì bài phải do chính em chấm bằng tay.","hs":"- HS nhận ra tranh được tạo nên từ nhiều chấm màu nhỏ khi xem ảnh phóng to.\n- HS phân biệt được hình do máy vẽ với bức tranh do chính mình chấm."}],"status":"checked","source":"KHBD Mĩ thuật 1 KNTT (Bút Xanh) — Chủ đề 2, Tiết 1"},
{"lop":1,"mon":"Mĩ thuật","tuan":4,"tiet":4,"bai":"Chủ đề 2: Sáng tạo từ những chấm màu (Tiết 2)","yccd":"1. Năng lực mĩ thuật\n- Nhận biết được yếu tố chấm trong sản phẩm, tác phẩm mĩ thuật.\n- Tạo được chấm từ màu (sáp, chì, màu nước…).\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động thực hành tạo chấm bằng màu.\n- Giao tiếp và hợp tác: Trao đổi, chia sẻ cách làm với bạn.\n3. Phẩm chất\n- Chăm chỉ: Kiên trì hoàn thành sản phẩm.\n- Trách nhiệm: Giữ vệ sinh khi dùng màu.\n4. Tích hợp\n- Năng lực số 3.2 CB1 (Tích hợp và tinh chỉnh nội dung số): HS nhận ra chấm dày tạo mảng đậm, chấm thưa tạo mảng nhạt qua thao tác mẫu trên ứng dụng vẽ.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 1; một số hình ảnh về chấm trong sản phẩm mĩ thuật; máy chiếu (nếu có).\n- Học sinh: đồ dùng học tập thiết yếu; màu dạng nước, giấy trắng, tăm bông, que gỗ tròn nhỏ.","hoatdong":[{"ten":"1. Khởi động","gv":"Mục tiêu: Ôn lại tiết trước, dẫn vào tạo chấm bằng màu.\n- GV cho HS xem lại sản phẩm chấm từ hạt và hỏi: “Ngoài hạt, còn cách nào tạo chấm nữa không?”\n- GV dẫn vào bài.","hs":"- HS nhớ lại và trả lời: dùng màu, chấm bằng bút.\n- HS lắng nghe."},{"ten":"2. Khám phá - Chấm màu trong mĩ thuật","gv":"Mục tiêu: Nhận biết yếu tố chấm trong sản phẩm mĩ thuật.\n- GV căn cứ hình minh hoạ trong sách hoặc giáo cụ trực quan, đặt câu hỏi giúp HS nhận biết chấm trong tranh, sản phẩm mĩ thuật.\n- GV giải thích thêm về chấm màu trong sản phẩm mĩ thuật.","hs":"- HS trình bày hiểu biết về sự xuất hiện của chấm trong sản phẩm mĩ thuật.\n- HS lắng nghe và đặt câu hỏi khi chưa hiểu."},{"ten":"3. Luyện tập - Sáng tạo: Tạo chấm từ màu","gv":"Mục tiêu: Tạo được chấm từ họa phẩm.\n- GV yêu cầu HS tạo chấm từ một số loại họa phẩm (sáp, chì, màu nước) bằng tăm bông, que gỗ tròn.\n- Mức độ cần đạt: Bắt buộc: tạo được vài chấm màu; Khuyến khích: xếp chấm màu tạo thành mảng/hình.","hs":"- HS thực hành tạo chấm từ họa phẩm.\n- HS xếp chấm màu thành mảng, hình theo ý thích."},{"ten":"4. Vận dụng - Chấm màu tạo bức tranh nhỏ","gv":"Mục tiêu: Dùng chấm màu tạo một hình đơn giản.\n- GV gợi ý HS dùng nhiều chấm màu ghép thành một hình đơn giản (bông hoa, quả).\n- GV nhận xét, khen ngợi.","hs":"- HS dùng chấm màu ghép thành hình đơn giản.\n- HS lắng nghe."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV mở ứng dụng vẽ trên máy tính nối máy chiếu, chọn cỡ đầu bút to nhỏ khác nhau rồi chấm mẫu một hàng chấm thưa và một hàng chấm dày để HS thấy chấm dày cho mảng màu đậm, chấm thưa cho mảng màu nhạt.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV mời lần lượt vài HS lên chấm thử vài chấm trên bảng tương tác theo hướng dẫn từng bước, sau đó cả lớp quay về chấm màu trên giấy của mình.\n⚠ (Miền 4: An toàn) Chỉ HS được mời mới chạm vào máy, chạm nhẹ đầu ngón tay, không tì mạnh vào màn hình; tay còn dính màu phải lau sạch trước khi chạm vào thiết bị.","hs":"- HS nhận ra chấm dày tạo mảng đậm, chấm thưa tạo mảng nhạt qua thao tác mẫu trên ứng dụng vẽ.\n- HS chấm thử được vài chấm trên máy theo hướng dẫn rồi chấm bài của mình trên giấy."}],"status":"checked","source":"KHBD Mĩ thuật 1 KNTT (Bút Xanh) — Chủ đề 2, Tiết 2"},
{"lop":1,"mon":"Mĩ thuật","tuan":5,"tiet":5,"bai":"Chủ đề 2: Sáng tạo từ những chấm màu (Tiết 3)","yccd":"1. Năng lực mĩ thuật\n- Biết cách sắp xếp chấm để tạo nét, tạo hình và trang trí sản phẩm.\n- Thực hiện được các bước trang trí một đồ vật bằng chấm màu; trưng bày, chia sẻ sản phẩm.\n2. Năng lực chung\n- Giao tiếp và hợp tác: Giới thiệu sản phẩm, lắng nghe nhận xét của bạn.\n- Giải quyết vấn đề và sáng tạo: Sắp xếp chấm màu có chủ đích để trang trí.\n3. Phẩm chất\n- Chăm chỉ, trách nhiệm: Hoàn thành và giữ gìn sản phẩm.\n- Yêu nước: Yêu quý sản phẩm do mình và bạn tạo ra.\n4. Tích hợp\n- Năng lực số 2.1 CB1 (Tương tác thông qua công nghệ số): HS xem lại bài của mình và của bạn được chiếu to trên màn hình.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 1; máy chiếu (nếu có); một số đồ vật (cốc, đĩa giấy, vỏ hộp trắng) để trang trí.\n- Học sinh: sản phẩm mĩ thuật từ tiết 1, 2; Vở bài tập; màu, đồ dùng tạo chấm; một đồ vật để trang trí (nếu có).","hoatdong":[{"ten":"1. Khởi động","gv":"Mục tiêu: Ôn lại và dẫn vào trang trí bằng chấm màu.\n- GV cho HS xem một đồ vật được trang trí bằng chấm màu và hỏi: “Đồ vật này được trang trí như thế nào?”\n- GV dẫn vào bài.","hs":"- HS trả lời: trang trí bằng nhiều chấm màu.\n- HS lắng nghe."},{"ten":"2. Khám phá - Thảo luận cách sắp xếp chấm","gv":"Mục tiêu: Hiểu cách sắp xếp chấm để tạo hình thức liên tiếp, xen kẽ.\n- GV cho HS xem hình minh hoạ trang 15 (SHS), nêu câu hỏi để HS thảo luận về cách sắp xếp chấm màu.\n- GV giải thích cách sắp xếp chấm tạo hình thức liên tiếp, xen kẽ.","hs":"- HS thảo luận nhóm, phát biểu về cách sắp xếp chấm màu.\n- HS lắng nghe và đặt câu hỏi khi chưa hiểu."},{"ten":"3. Luyện tập - Trang trí đồ vật bằng chấm màu","gv":"Mục tiêu: Dùng chấm màu trang trí một đồ vật theo ý thích.\n- GV phân tích các bước dùng chấm màu trang trí (SHS trang 15).\n- GV cho HS vẽ đồ vật ra Vở bài tập/giấy A4 (hoặc dùng đồ vật đã chuẩn bị) và trang trí bằng chấm màu, sắp xếp theo ý thích.","hs":"- HS quan sát các bước và đặt câu hỏi khi chưa hiểu.\n- HS vẽ/trang trí đồ vật bằng chấm màu theo ý thích."},{"ten":"4. Vận dụng - Trưng bày, nhận xét cuối chủ đề","gv":"Mục tiêu: Trưng bày và giới thiệu sản phẩm.\n- GV trưng bày một số sản phẩm của HS trên bảng.\n- GV mời HS giới thiệu sản phẩm theo gợi ý.\n- GV nhận xét, khen ngợi và tổng kết chủ đề.","hs":"- HS bày sản phẩm lên trước mặt.\n- HS giới thiệu sản phẩm của mình theo câu hỏi gợi ý."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) GV chụp ảnh từng bài chấm màu, chiếu lần lượt lên màn hình cho cả lớp cùng ngắm; mỗi bạn được nghe hai lời nhận xét của bạn khác về bài của mình.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) GV làm mẫu cách nói lời nhận xét cho bạn vui: khen trước một điều cụ thể về màu hoặc cách chấm, rồi mới nói điều muốn góp ý.\n⚠ (Miền 4: An toàn) Ảnh bài của các bạn chỉ chiếu trong lớp, không gửi ra ngoài; khi bài của bạn hiện lên màn hình thì không chê bai, không cười chế nhạo.","hs":"- HS xem lại bài của mình và của bạn được chiếu to trên màn hình.\n- HS nói được lời khen cụ thể và lời góp ý nhẹ nhàng cho bạn."}],"status":"checked","source":"KHBD Mĩ thuật 1 KNTT (Bút Xanh) — Chủ đề 2, Tiết 3"},
{"lop":1,"mon":"Mĩ thuật","tuan":6,"tiet":6,"bai":"Chủ đề 3: Nét vẽ của em (Tiết 1)","yccd":"1. Năng lực mĩ thuật\n- Bước đầu nhận biết yếu tố nét trong một số đồ vật và sản phẩm mĩ thuật.\n- Mô phỏng, thể hiện được yếu tố nét có kích thước khác nhau bằng sáp màu.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động quan sát, gọi tên các loại nét.\n- Giao tiếp và hợp tác: Trao đổi nhóm về các loại nét.\n3. Phẩm chất\n- Chăm chỉ: Tích cực thực hành tạo nét.\n- Trách nhiệm: Giữ gìn đồ dùng học tập.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS gọi đúng tên các loại nét khi xem hình động vẽ từng nét.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 1; một số hình minh hoạ về nét và đồ vật có sử dụng nét trong trang trí; máy chiếu (nếu có).\n- Học sinh: Sách và Vở thực hành Mĩ thuật lớp 1, đồ dùng học tập; sáp màu.","hoatdong":[{"ten":"1. Khởi động","gv":"Mục tiêu: Khơi gợi chú ý đến nét.\n- GV vẽ nhanh lên bảng một nét thẳng, nét cong, nét gấp khúc và hỏi: “Các nét này giống gì?”\n- GV dẫn vào bài về nét.","hs":"- HS quan sát và liên tưởng: nét thẳng như que, nét cong như cầu vồng…\n- HS lắng nghe."},{"ten":"2. Khám phá - Nhận diện nét trong cuộc sống","gv":"Mục tiêu: Nhận biết một số loại nét và nét trong cuộc sống.\n- GV giới thiệu một số loại nét và đặc điểm nhận dạng.\n- GV hỏi về sự xuất hiện của nét trên hình minh hoạ, giúp HS nhận biết nét trong tự nhiên (trên đồ vật, con vật, cảnh vật).\n- GV gợi ý để HS liên tưởng nét ở những vật gần gũi.","hs":"- HS trao đổi nhóm 2, 4 và gọi tên loại nét.\n- HS trình bày về sự xuất hiện của nét trong tự nhiên.\n- HS trao đổi và trả lời."},{"ten":"3. Luyện tập - Sáng tạo: Tạo nét bằng sáp màu","gv":"Mục tiêu: Tạo được nét bằng sáp màu.\n- GV yêu cầu HS thực hành tạo nét bằng sáp màu (SHS trang 18).\n- Mức độ cần đạt: Bắt buộc: tạo được nét đơn lẻ; Khuyến khích: dùng nét tạo nên hình.\n- GV lưu ý HS có thể dùng đất nặn hoặc màu nước để tạo nét.","hs":"- HS dùng sáp màu để tạo nên những nét vẽ.\n- HS thử dùng nét tạo thành hình đơn giản."},{"ten":"4. Vận dụng - Tìm nét quanh em","gv":"Mục tiêu: Liên hệ nét với đồ vật quanh em.\n- GV cho HS tìm nét trên đồ vật trong lớp (viền cửa sổ, kẻ bảng, hoa văn trên áo).\n- GV nhận xét, khen ngợi.","hs":"- HS chỉ ra các nét trên đồ vật quanh mình.\n- HS lắng nghe."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu hình động vẽ lần lượt từng loại nét: nét thẳng, nét cong, nét gấp khúc, nét xoáy ốc; đường nét hiện dần theo hướng đi của đầu bút nên HS thấy rõ nét được tạo ra theo thứ tự nào, còn tranh in chỉ cho thấy nét đã vẽ xong.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV dừng hình động ở giữa chừng, hỏi HS đoán nét đang được vẽ là nét gì rồi cho chạy tiếp để cả lớp cùng kiểm tra.\n⚠ (Miền 4: An toàn) GV điều khiển hình động, HS ngồi tại chỗ quan sát; hình động chạy nhanh và nhiều màu dễ làm mỏi mắt nên chỉ xem trong ít phút rồi chuyển sang vẽ trên giấy.","hs":"- HS gọi đúng tên các loại nét khi xem hình động vẽ từng nét.\n- HS đoán được nét đang vẽ dở và tự kiểm tra lại kết quả."}],"status":"checked","source":"KHBD Mĩ thuật 1 KNTT (Bút Xanh) — Chủ đề 3, Tiết 1"},
{"lop":1,"mon":"Mĩ thuật","tuan":7,"tiet":7,"bai":"Chủ đề 3: Nét vẽ của em (Tiết 2)","yccd":"1. Năng lực mĩ thuật\n- Nhận biết được nét có trong sản phẩm mĩ thuật và biết phân biệt một số loại nét.\n- Biết dùng nét để vẽ và trang trí một hình đơn giản.\n2. Năng lực chung\n- Giao tiếp và hợp tác: Trao đổi nhóm, phát biểu về các loại nét.\n- Giải quyết vấn đề và sáng tạo: Vận dụng nét để trang trí.\n3. Phẩm chất\n- Chăm chỉ: Kiên trì hoàn thành.\n- Yêu nước: Yêu quý cái đẹp có nét trong cuộc sống.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 1; một số sản phẩm mĩ thuật có yếu tố nét trang trí; máy chiếu (nếu có).\n- Học sinh: sản phẩm mĩ thuật từ tiết 1; đồ dùng học tập; màu.","hoatdong":[{"ten":"1. Khởi động","gv":"Mục tiêu: Ôn lại và dẫn vào bài.\n- GV cho HS xem lại sản phẩm nét tiết trước và hỏi: “Em đã tạo được những nét nào?”\n- GV dẫn vào bài.","hs":"- HS trả lời, kể tên các nét mình đã tạo.\n- HS lắng nghe."},{"ten":"2. Khám phá - Thảo luận về các loại nét","gv":"Mục tiêu: Nhận biết và phân biệt các loại nét trong sản phẩm.\n- GV cho HS trao đổi nhóm (đôi hoặc nhóm bạn) về những nét có trong phần thực hành.\n- GV yêu cầu HS mở SHS, xem hình minh hoạ trang 19 và nêu câu hỏi để HS nhận biết các loại nét.","hs":"- HS trao đổi nhóm và phát biểu trả lời câu hỏi.\n- HS nhận biết, gọi tên các loại nét trong hình."},{"ten":"3. Luyện tập - Sáng tạo: Dùng nét vẽ và trang trí hình con voi","gv":"Mục tiêu: Dùng nét vẽ và trang trí một hình (không tô màu).\n- GV cho HS xem và phân tích các bước dùng nét vẽ, trang trí hình con voi (từ vẽ hình đến dùng nét màu để trang trí, lưu ý không tô kín màu).\n- GV giới thiệu một số sản phẩm mĩ thuật có yếu tố nét trong trang trí.","hs":"- HS quan sát các bước và đặt câu hỏi khi chưa hiểu.\n- HS vẽ hình và dùng nét trang trí hình theo hướng dẫn."},{"ten":"4. Vận dụng - Trang trí một hình bằng nét","gv":"Mục tiêu: Vận dụng nét trang trí một hình theo ý thích.\n- GV cho HS chọn một hình đơn giản (bông hoa, con cá) và dùng nhiều loại nét để trang trí.\n- GV nhận xét, khen ngợi.","hs":"- HS chọn hình và dùng nét trang trí theo ý thích.\n- HS lắng nghe."}],"status":"checked","source":"KHBD Mĩ thuật 1 KNTT (Bút Xanh) — Chủ đề 3, Tiết 2"},
{"lop":1,"mon":"Mĩ thuật","tuan":8,"tiet":8,"bai":"Chủ đề 3: Nét vẽ của em (Tiết 3)","yccd":"1. Năng lực mĩ thuật\n- Vận dụng được nét để tạo nên sản phẩm mĩ thuật (trang trí đồ vật/tạo hình).\n- Trưng bày và giới thiệu được sản phẩm; chia sẻ cảm nhận.\n2. Năng lực chung\n- Giao tiếp và hợp tác: Giới thiệu sản phẩm, nhận xét bài của bạn.\n- Giải quyết vấn đề và sáng tạo: Lựa chọn nét và chất liệu để tạo hình.\n3. Phẩm chất\n- Chăm chỉ, trách nhiệm: Hoàn thành và giữ gìn sản phẩm.\n- Yêu nước: Trân trọng sản phẩm của mình và bạn.\n4. Tích hợp\n- Năng lực số 2.1 CB1 (Tương tác thông qua công nghệ số): HS quan sát lưới ảnh bài vẽ và bình chọn kèm lí do.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 1; máy chiếu (nếu có).\n- Học sinh: Sách học sinh; Vở bài tập; màu, đồ dùng tạo hình; đất nặn hoặc chất liệu khác (nếu có).","hoatdong":[{"ten":"1. Khởi động","gv":"Mục tiêu: Dẫn vào tạo hình bằng nét.\n- GV cho HS xem một sản phẩm tạo hình có nét trang trí và hỏi: “Sản phẩm này dùng những nét nào?”\n- GV dẫn vào bài.","hs":"- HS trả lời, gọi tên các nét.\n- HS lắng nghe."},{"ten":"2. Khám phá - Chọn cách thể hiện","gv":"Mục tiêu: Lựa chọn cách tạo hình và trang trí bằng nét.\n- GV gợi ý hai trường hợp: dùng sáp màu để tạo hình trang trí; hoặc dùng đất nặn/chất liệu khác để tạo hình rồi dùng nét trang trí.\n- GV hướng dẫn HS chọn cách phù hợp.","hs":"- HS lựa chọn cách thể hiện phù hợp với chất liệu của mình.\n- HS lắng nghe."},{"ten":"3. Luyện tập - Sáng tạo: Tạo hình và trang trí bằng nét","gv":"Mục tiêu: Tạo hình một đồ vật và dùng nét trang trí.\n- GV cho HS thực hành vào Vở bài tập trang 13 (hoặc giấy A4), hoặc tạo hình từ đất nặn rồi dùng nét trang trí cho sinh động.\n- Mức độ cần đạt: Bắt buộc: dùng nét tạo hình và trang trí đơn giản; Khuyến khích: sắp xếp nét có chủ đích, sinh động.","hs":"- HS thực hành theo chất liệu mình lựa chọn.\n- HS dùng nét trang trí hình cho sinh động."},{"ten":"4. Vận dụng - Trưng bày, nhận xét cuối chủ đề","gv":"Mục tiêu: Trưng bày, giới thiệu và nhận xét sản phẩm.\n- GV trưng bày một số sản phẩm của HS trên bảng.\n- GV mời HS giới thiệu sản phẩm theo câu hỏi gợi ý; nhận xét, tổng kết chủ đề.","hs":"- HS bày sản phẩm lên trước mặt.\n- HS giới thiệu sản phẩm của mình theo câu hỏi gợi ý."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) GV chụp ảnh các bài vẽ nét, xếp thành lưới ảnh trên màn hình để cả lớp cùng nhìn được một lúc; HS giơ tay bình chọn bài có nét mềm mại nhất, bài có nét khoẻ nhất.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) GV nhắc mỗi bài đều có chỗ đáng khen và mời HS nói một điều mình thích ở bài chưa được nhiều bạn bình chọn.\n⚠ (Miền 4: An toàn) Ảnh bài vẽ do GV chụp và giữ trong máy của lớp; bình chọn để cùng vui, không nói bài của bạn xấu, không xếp xem bài của ai kém nhất.","hs":"- HS quan sát lưới ảnh bài vẽ và bình chọn kèm lí do.\n- HS nêu được một điều đáng khen ở bài của bạn ít được bình chọn."}],"status":"checked","source":"KHBD Mĩ thuật 1 KNTT (Bút Xanh) — Chủ đề 3, Tiết 3"},
{"lop":1,"mon":"Mĩ thuật","tuan":9,"tiet":9,"bai":"Chủ đề 4: Sáng tạo từ những hình cơ bản (Tiết 1)","yccd":"1. Năng lực mĩ thuật\n- Biết mô tả hình dáng của hình cơ bản (tam giác, vuông, tròn).\n- Vẽ và tô màu được một hình cơ bản mà em thích.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động quan sát, nhận biết hình cơ bản.\n- Giải quyết vấn đề và sáng tạo: Liên tưởng hình cơ bản đến đồ vật xung quanh.\n3. Phẩm chất\n- Chăm chỉ: Tích cực thực hành.\n- Trách nhiệm: Giữ gìn đồ dùng, giữ vệ sinh lớp học.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS chỉ ra được hình cơ bản tạo nên đồ vật khi xem hình vẽ chồng lên ảnh.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 1; mô hình 3 hình cơ bản bằng bìa cứng hoặc dây thép; một số hình minh hoạ đồ vật có dạng hình cơ bản; máy chiếu (nếu có).\n- Học sinh: Sách và Vở thực hành Mĩ thuật lớp 1, đồ dùng học tập; một hộp giấy sạch (vỏ hộp bánh, hộp sữa).","hoatdong":[{"ten":"1. Khởi động","gv":"Mục tiêu: Khơi gợi hứng thú với hình cơ bản.\n- GV giơ mô hình hình tam giác, hình vuông, hình tròn và hỏi: “Đây là hình gì?”\n- GV dẫn vào bài.","hs":"- HS gọi tên hình cơ bản.\n- HS lắng nghe."},{"ten":"2. Khám phá - Nhận diện hình cơ bản","gv":"Mục tiêu: Nhận biết hình cơ bản và hình cơ bản trong tranh vẽ.\n- GV đặt câu hỏi giúp HS quan sát và nhận biết về hình cơ bản.\n- GV đặt câu hỏi giúp HS nhận biết hình cơ bản trong tranh vẽ.","hs":"- HS trình bày hiểu biết về hình cơ bản và hình cơ bản trong tranh.\n- HS chỉ ra hình cơ bản trong hình minh hoạ."},{"ten":"3. Luyện tập - Sáng tạo: Vẽ hình cơ bản em thích","gv":"Mục tiêu: Vẽ và tô màu một hình cơ bản.\n- GV yêu cầu HS vẽ và tô màu một hình cơ bản mà em thích vào Vở bài tập/giấy A4.\n- GV lưu ý HS những cách vẽ hình cơ bản (SGV).","hs":"- HS thực hành vẽ và tô màu hình cơ bản vào Vở bài tập/giấy A4."},{"ten":"4. Vận dụng - Tìm hình cơ bản quanh em","gv":"Mục tiêu: Liên hệ hình cơ bản với đồ vật quanh em.\n- GV cho HS tìm đồ vật có dạng hình cơ bản trong lớp (bảng vuông, đồng hồ tròn…).\n- GV nhận xét, khen ngợi.","hs":"- HS chỉ ra đồ vật có dạng hình cơ bản.\n- HS lắng nghe."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu ảnh đồ vật quen thuộc rồi dùng công cụ vẽ đè chồng hình tròn, hình vuông, hình tam giác lên ảnh để HS thấy rõ đồ vật ấy được ghép từ những hình cơ bản nào; thao tác chồng hình rồi xoá đi này không làm được trên tranh giấy.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu tiếp một loạt ảnh và cho HS thi gọi nhanh tên hình cơ bản có trong mỗi đồ vật.\n⚠ (Miền 4: An toàn) GV thao tác trên máy, HS ngồi tại chỗ trả lời; khi thi đua chỉ giơ tay, không chạy lên gần màn hình vì dễ vấp ngã và che tầm nhìn của bạn.","hs":"- HS chỉ ra được hình cơ bản tạo nên đồ vật khi xem hình vẽ chồng lên ảnh.\n- HS tham gia trò chơi gọi tên hình cơ bản của đồ vật."}],"status":"checked","source":"KHBD Mĩ thuật 1 KNTT (Bút Xanh) — Chủ đề 4, Tiết 1"},
{"lop":1,"mon":"Mĩ thuật","tuan":10,"tiet":10,"bai":"Chủ đề 4: Sáng tạo từ những hình cơ bản (Tiết 2)","yccd":"1. Năng lực mĩ thuật\n- Bước đầu hình thành khả năng quan sát, liên tưởng hình cơ bản đến đồ vật xung quanh.\n- Vẽ được đồ vật có dạng hình cơ bản và tô màu theo các cách khác nhau.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động phát hiện đồ vật có dạng hình cơ bản.\n- Giải quyết vấn đề và sáng tạo: Tô màu hình theo đặc tính của hình.\n3. Phẩm chất\n- Chăm chỉ: Kiên trì hoàn thành sản phẩm.\n- Trách nhiệm: Giữ vệ sinh khi dùng màu.\n4. Tích hợp\n- Năng lực số 6.1 CB1 (Hiểu biết về trí tuệ nhân tạo): HS xem và nêu ý kiến về các bộ màu do máy gợi ý.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 1; mô hình hình cơ bản bằng dây thép, bìa; máy chiếu (nếu có).\n- Học sinh: đồ dùng học tập thiết yếu; Vở bài tập/giấy A4; màu.","hoatdong":[{"ten":"1. Khởi động","gv":"Mục tiêu: Ôn lại và dẫn vào bài.\n- GV cho HS kể nhanh đồ vật có dạng hình cơ bản đã tìm được ở tiết trước.\n- GV dẫn vào bài.","hs":"- HS kể đồ vật có dạng hình cơ bản.\n- HS lắng nghe."},{"ten":"2. Khám phá - Nhận diện đồ vật có dạng hình cơ bản","gv":"Mục tiêu: Nhận biết đồ vật có dạng hình tam giác, vuông, tròn.\n- GV cho HS quan sát một số vật có dạng hình cơ bản trong SHS trang 23, 24, 25.\n- GV hỏi HS phát hiện xung quanh mình những đồ vật có dạng hình cơ bản.","hs":"- HS trình bày về những vật có dạng hình cơ bản xung quanh hoặc đã biết.\n- HS chỉ ra đồ vật có dạng hình cơ bản."},{"ten":"3. Luyện tập - Sáng tạo: Vẽ và tô màu đồ vật có dạng hình cơ bản","gv":"Mục tiêu: Vẽ và tô màu một vật có dạng hình cơ bản.\n- GV cho HS quan sát các cách tô sáp màu vào hình cơ bản khác nhau (SHS trang 26–28).\n- GV yêu cầu HS vẽ và tô màu một vật có dạng hình cơ bản.\n- Mức độ cần đạt: Bắt buộc: vẽ được một vật có dạng hình cơ bản và tô kín hình; Khuyến khích: vẽ 2 vật và tô màu theo đặc tính của hình.","hs":"- HS quan sát các cách tô màu và đặt câu hỏi khi chưa hiểu.\n- HS thực hành vẽ và tô màu vào Vở bài tập/giấy A4."},{"ten":"4. Vận dụng - Tô màu sáng tạo","gv":"Mục tiêu: Tô màu hình cơ bản theo nhiều cách.\n- GV gợi ý HS thử tô màu chuyển sắc, tô chấm, tô nét trong cùng một hình.\n- GV nhận xét, khen ngợi.","hs":"- HS thử các cách tô màu khác nhau.\n- HS lắng nghe."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 1) GV mở công cụ gợi ý phối màu, chọn một màu HS thích rồi để máy đề xuất vài màu đi kèm; GV nói rõ máy chọn theo những cách phối màu người ta hay dùng nên có bộ nhìn đẹp, có bộ lại không hợp với bài của mình.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS so sánh bộ màu máy gợi ý với những màu có thật trong hộp sáp của mình rồi chọn bộ màu mình thấy hợp nhất cho hình của mình.\n⚠ (Miền 4: An toàn) Cô giáo là người bấm máy, các em xem và nêu ý kiến; máy chỉ gợi ý, quyền chọn màu cuối cùng cho bài của em vẫn là của em.","hs":"- HS xem và nêu ý kiến về các bộ màu do máy gợi ý.\n- HS tự chọn bộ màu cho bài của mình và nói được lí do chọn."}],"status":"checked","source":"KHBD Mĩ thuật 1 KNTT (Bút Xanh) — Chủ đề 4, Tiết 2"},
{"lop":1,"mon":"Mĩ thuật","tuan":11,"tiet":11,"bai":"Chủ đề 4: Sáng tạo từ những hình cơ bản (Tiết 3)","yccd":"1. Năng lực mĩ thuật\n- Biết sử dụng hình cơ bản trong trang trí đồ vật đơn giản.\n- Xây dựng được ý tưởng sử dụng hình cơ bản để trang trí một món đồ.\n2. Năng lực chung\n- Giao tiếp và hợp tác: Thảo luận nhóm, nhận xét bài của bạn.\n- Giải quyết vấn đề và sáng tạo: Lên ý tưởng trang trí bằng hình cơ bản.\n3. Phẩm chất\n- Chăm chỉ: Tích cực xây dựng ý tưởng.\n- Trách nhiệm: Sử dụng vật liệu tái sử dụng, giữ vệ sinh.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 1; máy chiếu (nếu có).\n- Học sinh: sản phẩm mĩ thuật từ tiết 1, 2; Vở bài tập/giấy A4; màu, đồ dùng học tập; một vỏ hộp giấy.","hoatdong":[{"ten":"1. Khởi động","gv":"Mục tiêu: Dẫn vào trang trí bằng hình cơ bản.\n- GV cho HS xem một lọ hoa được trang trí bằng hình cơ bản và hỏi cách trang trí.\n- GV dẫn vào bài.","hs":"- HS trả lời: dùng hình vuông, tròn, tam giác để trang trí.\n- HS lắng nghe."},{"ten":"2. Khám phá - Thảo luận về hình cơ bản trong trang trí","gv":"Mục tiêu: Nhận biết cách dùng hình cơ bản để trang trí.\n- GV chia nhóm cho HS thảo luận theo câu hỏi gợi ý trong SGV.\n- GV phân tích các bước dùng hình cơ bản trang trí một chiếc lọ hoa (SHS trang 30–31).","hs":"- HS quan sát bài của bạn và trả lời theo nhóm/cá nhân.\n- HS quan sát các bước và đặt câu hỏi khi chưa hiểu."},{"ten":"3. Luyện tập - Xây dựng ý tưởng trang trí","gv":"Mục tiêu: Vẽ ý tưởng sử dụng hình cơ bản để trang trí một món đồ.\n- GV cho HS vẽ ý tưởng sử dụng hình cơ bản để trang trí một món đồ (tạo hình từ vỏ hộp) ra Vở bài tập/giấy A4.\n- GV gợi ý HS chọn hình cơ bản yêu thích để trang trí.","hs":"- HS vẽ đồ vật cần trang trí ra Vở bài tập/giấy A4.\n- HS sử dụng hình cơ bản yêu thích để trang trí."},{"ten":"4. Vận dụng - Chia sẻ ý tưởng","gv":"Mục tiêu: Trình bày ý tưởng trang trí.\n- GV mời một số HS giới thiệu ý tưởng của mình.\n- GV nhận xét, khen ngợi, dặn chuẩn bị vật liệu cho tiết sau.","hs":"- HS giới thiệu ý tưởng trang trí của mình.\n- HS lắng nghe."}],"status":"checked","source":"KHBD Mĩ thuật 1 KNTT (Bút Xanh) — Chủ đề 4, Tiết 3"},
{"lop":1,"mon":"Mĩ thuật","tuan":12,"tiet":12,"bai":"Chủ đề 4: Sáng tạo từ những hình cơ bản (Tiết 4)","yccd":"1. Năng lực mĩ thuật\n- Sử dụng được vật liệu sẵn có để tạo và trang trí đồ vật bằng hình cơ bản.\n- Sắp xếp được sản phẩm cá nhân thành sản phẩm nhóm; trưng bày, chia sẻ cảm nhận.\n2. Năng lực chung\n- Giao tiếp và hợp tác: Cùng nhóm hoàn thành và giới thiệu sản phẩm.\n- Giải quyết vấn đề và sáng tạo: Sử dụng hình cơ bản trang trí có chủ đích.\n3. Phẩm chất\n- Chăm chỉ, trách nhiệm: Hoàn thành và giữ gìn sản phẩm.\n- Yêu nước: Trân trọng sản phẩm của mình và bạn.\n4. Tích hợp\n- Năng lực số 3.2 CB1 (Tích hợp và tinh chỉnh nội dung số): HS xem phòng trưng bày trên màn hình và nhận ra sản phẩm của mình.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 1; máy chiếu (nếu có).\n- Học sinh: vỏ hộp đã chuẩn bị; màu/giấy màu, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"Mục tiêu: Dẫn vào thực hành trang trí.\n- GV cho HS nhắc lại ý tưởng trang trí đã vẽ ở tiết trước.\n- GV dẫn vào bài.","hs":"- HS nhắc lại ý tưởng của mình.\n- HS lắng nghe."},{"ten":"2. Khám phá - Xem lại các bước tạo hình đồ vật","gv":"Mục tiêu: Nắm các bước tạo và trang trí đồ vật từ vỏ hộp.\n- GV nhắc lại các bước: tạo hình đồ vật từ vỏ hộp, sau đó sử dụng hình cơ bản để trang trí như ý tưởng đã vẽ.","hs":"- HS lắng nghe và hình dung các bước.\n- HS đặt câu hỏi khi chưa hiểu."},{"ten":"3. Luyện tập - Sáng tạo: Trang trí đồ vật bằng hình cơ bản","gv":"Mục tiêu: Tạo hình và trang trí một đồ vật từ vỏ hộp.\n- GV cho HS tạo hình một đồ vật từ vỏ hộp đã chuẩn bị theo hình vẽ ý tưởng, dùng hình cơ bản để trang trí.\n- Mức độ cần đạt: Bắt buộc: trang trí một vật có sử dụng hình cơ bản; Khuyến khích: sắp xếp chính phụ có chủ đích.","hs":"- HS sử dụng hình cơ bản để trang trí một đồ vật theo ý tưởng của mình."},{"ten":"4. Vận dụng - Trưng bày, nhận xét cuối chủ đề","gv":"Mục tiêu: Trưng bày, giới thiệu và nhận xét sản phẩm.\n- GV bày một số sản phẩm của HS trên bảng.\n- GV mời HS giới thiệu sản phẩm theo câu hỏi gợi ý; nhận xét, tổng kết chủ đề.","hs":"- HS bày sản phẩm lên trước mặt.\n- HS giới thiệu sản phẩm của mình theo câu hỏi gợi ý."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV chụp ảnh sản phẩm của cả lớp, ghép thành một trang “phòng trưng bày” có ô ảnh và tên bạn ở dưới mỗi ô, chiếu cho cả lớp cùng xem như đi xem triển lãm thật.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) HS lần lượt đứng lên giới thiệu ô ảnh của mình: em làm đồ vật gì, em ghép từ những hình cơ bản nào.\n⚠ (Miền 4: An toàn) Dưới mỗi ô ảnh chỉ ghi tên gọi ở lớp của bạn, không ghi họ tên đầy đủ, không ghi lớp và tên trường; trang trưng bày chỉ mở trong lớp học.","hs":"- HS xem phòng trưng bày trên màn hình và nhận ra sản phẩm của mình.\n- HS giới thiệu ngắn được về sản phẩm của mình trước lớp."}],"status":"checked","source":"KHBD Mĩ thuật 1 KNTT (Bút Xanh) — Chủ đề 4, Tiết 4"},
{"lop":1,"mon":"Mĩ thuật","tuan":13,"tiet":13,"bai":"Chủ đề 5: Màu cơ bản trong mĩ thuật (Tiết 1)","yccd":"1. Năng lực mĩ thuật\n- Nhận biết và đọc được tên ba màu cơ bản (đỏ, vàng, lam) trên đồ vật, sự vật.\n- Vẽ được một hình có màu cơ bản mà em thích.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động nhận biết màu cơ bản.\n- Giải quyết vấn đề và sáng tạo: Thử pha màu để hiểu về màu cơ bản.\n3. Phẩm chất\n- Chăm chỉ: Tích cực thực hành.\n- Trách nhiệm: Giữ vệ sinh khi dùng màu.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nêu được hai màu cơ bản pha ra màu mới nào sau khi xem mô phỏng.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 1; bảng màu cơ bản; một số đồ vật có màu cơ bản; tranh minh hoạ; máy chiếu (nếu có).\n- Học sinh: Sách và Vở thực hành Mĩ thuật lớp 1, đồ dùng học tập; màu (nước/sáp), đất nặn.","hoatdong":[{"ten":"1. Khởi động","gv":"Mục tiêu: Khơi gợi chú ý đến màu sắc.\n- GV giơ bảng màu cơ bản và hỏi: “Em biết tên những màu này không?”\n- GV dẫn vào bài về màu cơ bản.","hs":"- HS gọi tên các màu: đỏ, vàng, lam (xanh).\n- HS lắng nghe."},{"ten":"2. Khám phá - Nhận diện màu cơ bản","gv":"Mục tiêu: Nhận biết ba màu cơ bản và màu cơ bản trong tranh.\n- GV đặt câu hỏi giúp HS quan sát và nhận biết về ba màu cơ bản.\n- GV giải thích về màu cơ bản bằng cách kết hợp màu (nước, đất nặn) để tạo màu mới.","hs":"- HS trình bày hiểu biết về màu cơ bản và màu cơ bản trong tranh.\n- HS tham gia thực hành để hiểu khái niệm màu cơ bản tạo nên màu khác."},{"ten":"3. Luyện tập - Sáng tạo: Vẽ hình có màu cơ bản","gv":"Mục tiêu: Vẽ một hình có màu cơ bản em thích.\n- GV cho HS thể hiện một hình có màu cơ bản yêu thích vào Vở bài tập/giấy A4.\n- GV quan sát, hỗ trợ HS chọn và dùng màu.","hs":"- HS thực hành vẽ hình có màu cơ bản vào Vở bài tập/giấy A4."},{"ten":"4. Vận dụng - Tìm màu cơ bản quanh em","gv":"Mục tiêu: Liên hệ màu cơ bản với đồ vật quanh em.\n- GV cho HS tìm đồ vật có màu đỏ, vàng, lam trong lớp học.\n- GV nhận xét, khen ngợi.","hs":"- HS chỉ ra đồ vật có màu cơ bản.\n- HS lắng nghe."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu mô phỏng pha màu: kéo giọt màu đỏ chồng lên giọt màu vàng, màu cam hiện ra ngay trên màn hình; làm lại với đỏ và lam, vàng và lam. Pha bằng màu bột mất nhiều thời gian, mô phỏng cho HS thấy kết quả tức thì và thử lại được nhiều lần.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV kéo thêm ít hoặc nhiều màu để HS thấy tỉ lệ khác nhau thì cho ra màu cam đậm hay cam nhạt.\n⚠ (Miền 4: An toàn) GV thao tác trên máy; sau khi xem mô phỏng, HS phải pha màu thật bằng bút lông và nước để tự tay cảm nhận, không thay việc pha màu thật bằng màn hình.","hs":"- HS nêu được hai màu cơ bản pha ra màu mới nào sau khi xem mô phỏng.\n- HS pha lại màu đó bằng màu vẽ thật và so sánh với kết quả trên màn hình."}],"status":"checked","source":"KHBD Mĩ thuật 1 KNTT (Bút Xanh) — Chủ đề 5, Tiết 1"},
{"lop":1,"mon":"Mĩ thuật","tuan":14,"tiet":14,"bai":"Chủ đề 5: Màu cơ bản trong mĩ thuật (Tiết 2)","yccd":"1. Năng lực mĩ thuật\n- Bước đầu hình thành khả năng quan sát, liên tưởng đến một số đồ vật, sự vật có màu cơ bản.\n- Vẽ, xé, dán hoặc đắp nổi một vật có dạng màu cơ bản mà em thích.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động chọn hình thức thể hiện.\n- Giải quyết vấn đề và sáng tạo: Tô màu theo đặc tính của hình.\n3. Phẩm chất\n- Chăm chỉ: Kiên trì hoàn thành sản phẩm.\n- Trách nhiệm: Giữ vệ sinh khi thực hành.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 1; ảnh vật có màu cơ bản gần gũi với HS ở địa phương; máy chiếu (nếu có).\n- Học sinh: đồ dùng học tập thiết yếu; Vở bài tập/giấy A4; màu, giấy màu.","hoatdong":[{"ten":"1. Khởi động","gv":"Mục tiêu: Ôn lại và dẫn vào bài.\n- GV cho HS kể nhanh đồ vật có màu cơ bản.\n- GV dẫn vào bài.","hs":"- HS kể đồ vật có màu cơ bản.\n- HS lắng nghe."},{"ten":"2. Khám phá - Nhận diện vật có màu cơ bản","gv":"Mục tiêu: Nhận biết đồ vật có màu cơ bản.\n- GV cho HS quan sát một số vật có dạng màu cơ bản trong SHS trang 33.\n- GV hỏi HS phát hiện xung quanh mình những đồ vật có màu cơ bản.","hs":"- HS trình bày về những đồ vật có màu cơ bản xung quanh hoặc đã biết.\n- HS chỉ ra đồ vật có màu cơ bản."},{"ten":"3. Luyện tập - Sáng tạo: Thể hiện vật có màu cơ bản","gv":"Mục tiêu: Vẽ, xé, dán hoặc đắp nổi một vật có màu cơ bản.\n- GV cho HS thể hiện một vật có màu cơ bản yêu thích bằng hình thức tự chọn.\n- Mức độ cần đạt: Bắt buộc: tạo hình một vật có màu cơ bản và tô màu; Khuyến khích: vẽ 1–2 vật và tô màu theo đặc tính của hình.","hs":"- HS thực hành vào Vở bài tập/giấy A4 bằng hình thức tự chọn (vẽ, xé, dán)."},{"ten":"4. Vận dụng - Trưng bày nhanh","gv":"Mục tiêu: Chia sẻ sản phẩm.\n- GV cho HS giơ sản phẩm và giới thiệu ngắn màu cơ bản đã dùng.\n- GV nhận xét, khen ngợi.","hs":"- HS giơ và giới thiệu sản phẩm.\n- HS lắng nghe."}],"status":"checked","source":"KHBD Mĩ thuật 1 KNTT (Bút Xanh) — Chủ đề 5, Tiết 2"},
{"lop":1,"mon":"Mĩ thuật","tuan":15,"tiet":15,"bai":"Chủ đề 5: Màu cơ bản trong mĩ thuật (Tiết 3)","yccd":"1. Năng lực mĩ thuật\n- Biết sử dụng màu cơ bản trong thực hành, sáng tạo, trang trí.\n- Xây dựng được ý tưởng sử dụng màu cơ bản để trang trí một món đồ chơi.\n2. Năng lực chung\n- Giao tiếp và hợp tác: Thảo luận nhóm, nhận xét bài của bạn.\n- Giải quyết vấn đề và sáng tạo: Lên ý tưởng trang trí bằng màu cơ bản.\n3. Phẩm chất\n- Chăm chỉ: Tích cực xây dựng ý tưởng.\n- Trách nhiệm: Tận dụng đồ chơi cũ, giữ vệ sinh.\n4. Tích hợp\n- Năng lực số 6.1 CB1 (Hiểu biết về trí tuệ nhân tạo): HS nêu ý kiến về các cách phối ba màu cơ bản do máy gợi ý.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 1; máy chiếu (nếu có).\n- Học sinh: sản phẩm từ tiết 1, 2; Vở bài tập/giấy A4; màu, đồ dùng học tập; một món đồ chơi cũ.","hoatdong":[{"ten":"1. Khởi động","gv":"Mục tiêu: Dẫn vào trang trí bằng màu cơ bản.\n- GV cho HS xem một trống đồ chơi được trang trí bằng màu cơ bản và hỏi cách trang trí.\n- GV dẫn vào bài.","hs":"- HS trả lời: dùng màu đỏ, vàng, lam để trang trí.\n- HS lắng nghe."},{"ten":"2. Khám phá - Thảo luận về trang trí bằng màu cơ bản","gv":"Mục tiêu: Nhận biết cách dùng màu cơ bản để trang trí.\n- GV chia nhóm cho HS thảo luận theo câu hỏi gợi ý trong SHS.\n- GV phân tích các bước dùng màu cơ bản trang trí một chiếc trống đồ chơi (SHS trang 38–39); lưu ý kết hợp yếu tố tạo hình: chấm, nét, hình.","hs":"- HS quan sát bài của bạn và trả lời theo nhóm/cá nhân.\n- HS quan sát các bước và đặt câu hỏi khi chưa hiểu."},{"ten":"3. Luyện tập - Xây dựng ý tưởng trang trí đồ chơi","gv":"Mục tiêu: Vẽ ý tưởng sử dụng màu cơ bản để trang trí một món đồ chơi.\n- GV cho HS vẽ ý tưởng sử dụng màu cơ bản để trang trí một món đồ chơi ra Vở bài tập/giấy A4.\n- GV gợi ý HS chọn màu cơ bản yêu thích để trang trí.","hs":"- HS vẽ đồ vật cần trang trí ra Vở bài tập/giấy A4.\n- HS sử dụng màu cơ bản yêu thích để trang trí."},{"ten":"4. Vận dụng - Chia sẻ ý tưởng","gv":"Mục tiêu: Trình bày ý tưởng trang trí.\n- GV mời một số HS giới thiệu ý tưởng của mình.\n- GV nhận xét, dặn HS chuẩn bị đồ chơi cũ cho tiết sau.","hs":"- HS giới thiệu ý tưởng trang trí của mình.\n- HS lắng nghe."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 1) GV dùng công cụ gợi ý màu, nhập ba màu cơ bản đỏ, vàng, lam và cho máy đề xuất vài cách sắp xếp ba màu ấy trên một món đồ chơi; HS xem và nói cách nào nhìn thích mắt.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu cạnh đó ảnh vài món đồ chơi thật dùng ba màu cơ bản để HS đối chiếu xem cách người thợ làm và cách máy gợi ý khác nhau ở chỗ nào.\n⚠ (Miền 4: An toàn) Cô giáo gõ và bấm máy, các em xem rồi nêu ý kiến; máy chỉ gợi ý, món đồ chơi của em vẫn do chính em chọn màu và tự trang trí.","hs":"- HS nêu ý kiến về các cách phối ba màu cơ bản do máy gợi ý.\n- HS chọn cách phối màu cho món đồ chơi của mình và nói vì sao chọn."}],"status":"checked","source":"KHBD Mĩ thuật 1 KNTT (Bút Xanh) — Chủ đề 5, Tiết 3"},
{"lop":1,"mon":"Mĩ thuật","tuan":16,"tiet":16,"bai":"Chủ đề 5: Màu cơ bản trong mĩ thuật (Tiết 4)","yccd":"1. Năng lực mĩ thuật\n- Sử dụng được màu cơ bản để trang trí một món đồ chơi cũ yêu thích.\n- Trưng bày và giới thiệu được sản phẩm; chia sẻ cảm nhận.\n2. Năng lực chung\n- Giao tiếp và hợp tác: Giới thiệu sản phẩm, nhận xét bài của bạn.\n- Giải quyết vấn đề và sáng tạo: Sắp xếp màu cơ bản hài hoà.\n3. Phẩm chất\n- Chăm chỉ, trách nhiệm: Hoàn thành, giữ gìn sản phẩm, tái sử dụng đồ chơi cũ.\n- Yêu nước: Trân trọng sản phẩm của mình và bạn.\n4. Tích hợp\n- Năng lực số 3.2 CB1 (Tích hợp và tinh chỉnh nội dung số): HS xem ảnh món đồ chơi của các nhóm trên màn hình.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 1; máy chiếu (nếu có).\n- Học sinh: món đồ chơi cũ đã chuẩn bị; màu/giấy màu, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"Mục tiêu: Dẫn vào thực hành trang trí.\n- GV cho HS nhắc lại ý tưởng trang trí đồ chơi đã vẽ ở tiết trước.\n- GV dẫn vào bài.","hs":"- HS nhắc lại ý tưởng của mình.\n- HS lắng nghe."},{"ten":"2. Khám phá - Xem lại cách trang trí","gv":"Mục tiêu: Nắm cách trang trí đồ chơi bằng màu cơ bản.\n- GV nhắc lại cách sử dụng màu cơ bản kết hợp chấm, nét, hình để trang trí món đồ chơi theo ý tưởng.","hs":"- HS lắng nghe và hình dung cách làm.\n- HS đặt câu hỏi khi chưa hiểu."},{"ten":"3. Luyện tập - Sáng tạo: Trang trí món đồ chơi cũ","gv":"Mục tiêu: Dùng màu cơ bản trang trí món đồ chơi cũ.\n- GV cho HS sử dụng màu cơ bản trang trí một món đồ chơi đã chuẩn bị theo ý tưởng đã thể hiện.\n- Mức độ cần đạt: Bắt buộc: trang trí món đồ chơi có sử dụng màu cơ bản; Khuyến khích: sắp xếp màu theo nguyên lí tạo hình đơn giản.","hs":"- HS sử dụng màu cơ bản để trang trí món đồ chơi theo ý tưởng của mình."},{"ten":"4. Vận dụng - Trưng bày, nhận xét cuối chủ đề","gv":"Mục tiêu: Trưng bày, giới thiệu và nhận xét sản phẩm.\n- GV bày một số sản phẩm của HS trên bảng.\n- GV mời HS giới thiệu món đồ chơi đã trang trí theo câu hỏi gợi ý; nhận xét, tổng kết chủ đề.","hs":"- HS bày sản phẩm lên trước mặt.\n- HS giới thiệu sản phẩm của mình theo câu hỏi gợi ý."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV chụp món đồ chơi đã trang trí của từng nhóm từ hai phía, ghép thành một trang giới thiệu có ảnh và tên nhóm rồi chiếu cho cả lớp cùng xem.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) Các nhóm lần lượt giới thiệu món đồ chơi qua ảnh trên màn hình: nhóm đã dùng những màu nào, món đồ chơi này chơi thế nào.\n⚠ (Miền 4: An toàn) Ảnh chỉ chụp món đồ chơi, không chụp mặt các bạn khi chưa hỏi bạn; trang giới thiệu chỉ chiếu trong lớp và cho cha mẹ xem khi họp lớp.","hs":"- HS xem ảnh món đồ chơi của các nhóm trên màn hình.\n- HS giới thiệu được món đồ chơi của nhóm mình trước lớp."}],"status":"checked","source":"KHBD Mĩ thuật 1 KNTT (Bút Xanh) — Chủ đề 5, Tiết 4"},
{"lop":1,"mon":"Mĩ thuật","tuan":17,"tiet":17,"bai":"Chủ đề 6: Sáng tạo từ những khối cơ bản (Tiết 1)","yccd":"1. Năng lực mĩ thuật\n- Nhận biết được một số dạng khối cơ bản (khối cầu, khối trụ, khối lập phương…).\n- Tạo hình được một số khối cơ bản từ đất nặn.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động quan sát, nhận biết khối cơ bản.\n- Giải quyết vấn đề và sáng tạo: Thao tác nặn tạo khối.\n3. Phẩm chất\n- Chăm chỉ: Tích cực thực hành.\n- Trách nhiệm: Giữ vệ sinh, an toàn khi dùng đất nặn.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS gọi tên khối và chỉ ra các mặt của khối khi xem hình xoay.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 1; mô hình khối cơ bản bằng bìa hoặc thạch cao; một số đồ vật có dạng khối cơ bản; máy chiếu (nếu có).\n- Học sinh: Sách và Vở thực hành Mĩ thuật lớp 1, đồ dùng học tập; đất nặn.","hoatdong":[{"ten":"1. Khởi động","gv":"Mục tiêu: Khơi gợi chú ý đến khối.\n- GV giơ mô hình khối cầu, khối trụ, khối lập phương và hỏi: “Các khối này khác hình phẳng ở chỗ nào?”\n- GV dẫn vào bài về khối cơ bản.","hs":"- HS quan sát và trả lời: khối có chiều cao, ngang, sâu; cầm nắm được.\n- HS lắng nghe."},{"ten":"2. Khám phá - Nhận diện khối cơ bản","gv":"Mục tiêu: Nhận biết một số dạng khối cơ bản.\n- GV đặt câu hỏi giúp HS quan sát và nhận biết về một số dạng khối cơ bản. Lưu ý chiều cao, chiều ngang và chiều sâu của khối.\n- GV thao tác trên khối thật để HS nhận biết về diện, đáy của khối.","hs":"- HS trình bày hiểu biết về một số dạng khối cơ bản.\n- HS quan sát thao tác trên khối thật."},{"ten":"3. Luyện tập - Sáng tạo: Nặn khối cơ bản","gv":"Mục tiêu: Nặn được khối cơ bản từ đất nặn.\n- GV hướng dẫn (thị phạm) cách tạo khối từ đất nặn qua hình minh hoạ trang 45, 46 (SHS).\n- GV lưu ý HS thao tác an toàn với đất nặn.","hs":"- HS thực hiện các thao tác để tạo khối từ đất nặn."},{"ten":"4. Vận dụng - Tìm khối cơ bản quanh em","gv":"Mục tiêu: Liên hệ khối cơ bản với đồ vật quanh em.\n- GV cho HS tìm đồ vật có dạng khối cơ bản trong lớp (hộp phấn, quả bóng, lon nước…).\n- GV nhận xét, khen ngợi.","hs":"- HS chỉ ra đồ vật có dạng khối cơ bản.\n- HS lắng nghe."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu mô hình khối lập phương, khối cầu, khối trụ dạng ba chiều và xoay chậm để HS thấy mặt trước, mặt bên, mặt trên của cùng một khối; cầm khối gỗ trên tay thì chỉ một bạn nhìn được, xoay trên màn hình thì cả lớp cùng nhìn rõ.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV dừng ở một góc xoay và hỏi HS đoán đó là khối gì, sau đó xoay tiếp cho cả lớp kiểm tra.\n⚠ (Miền 4: An toàn) GV điều khiển việc xoay hình; sau khi xem, HS cầm khối gỗ, hộp giấy thật để sờ và cảm nhận mặt phẳng, mặt cong bằng chính tay mình.","hs":"- HS gọi tên khối và chỉ ra các mặt của khối khi xem hình xoay.\n- HS đối chiếu được hình trên màn hình với khối thật cầm trên tay."}],"status":"checked","source":"KHBD Mĩ thuật 1 KNTT (Bút Xanh) — Chủ đề 6, Tiết 1"},
{"lop":1,"mon":"Mĩ thuật","tuan":18,"tiet":18,"bai":"Chủ đề 6: Sáng tạo từ những khối cơ bản (Tiết 2)","yccd":"1. Năng lực mĩ thuật\n- Liên tưởng được đồ vật có dạng khối cơ bản.\n- Tạo được một vật có dạng khối cơ bản từ đất nặn hoặc vật liệu tái sử dụng.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động phát hiện đồ vật có dạng khối cơ bản.\n- Giải quyết vấn đề và sáng tạo: Tạo hình vật từ khối.\n3. Phẩm chất\n- Chăm chỉ: Kiên trì hoàn thành sản phẩm.\n- Trách nhiệm: Dùng vật liệu tái sử dụng, giữ an toàn khi thực hành.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 1; ảnh vật có dạng khối cơ bản gần gũi với HS ở địa phương; máy chiếu (nếu có).\n- Học sinh: đất nặn; vật liệu tái sử dụng dạng khối; đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"Mục tiêu: Ôn lại và dẫn vào bài.\n- GV cho HS kể nhanh đồ vật có dạng khối cơ bản.\n- GV dẫn vào bài.","hs":"- HS kể đồ vật có dạng khối cơ bản.\n- HS lắng nghe."},{"ten":"2. Khám phá - Nhận diện vật có dạng khối cơ bản","gv":"Mục tiêu: Nhận biết và liên tưởng đồ vật có dạng khối cơ bản.\n- GV cho HS quan sát hình minh hoạ trang 41–44 giúp HS nhận biết và liên tưởng đến những vật có dạng khối cơ bản.\n- GV đặt câu hỏi để HS phát hiện xung quanh mình (trong lớp, ở nhà) những đồ vật có dạng khối cơ bản.","hs":"- HS trình bày về những đồ vật xung quanh hoặc đã biết có dạng khối cơ bản."},{"ten":"3. Luyện tập - Sáng tạo: Làm một vật có dạng khối cơ bản","gv":"Mục tiêu: Tạo một vật có dạng khối cơ bản từ đất nặn hoặc vật liệu tái sử dụng.\n- GV cho HS thể hiện một vật có dạng khối cơ bản yêu thích bằng đất nặn.\n- Mức độ cần đạt: Bắt buộc: nặn được một vật có dạng khối cơ bản đơn giản; Khuyến khích: tạo hình vật và trang trí thêm chi tiết.","hs":"- HS thực hiện một vật có dạng khối mình yêu thích."},{"ten":"4. Vận dụng - Chia sẻ sản phẩm","gv":"Mục tiêu: Giới thiệu sản phẩm.\n- GV mời một số HS giới thiệu vật mình đã nặn.\n- GV nhận xét, khen ngợi.","hs":"- HS giới thiệu vật mình đã nặn.\n- HS lắng nghe."}],"status":"checked","source":"KHBD Mĩ thuật 1 KNTT (Bút Xanh) — Chủ đề 6, Tiết 2"},
{"lop":1,"mon":"Mĩ thuật","tuan":19,"tiet":19,"bai":"Chủ đề 6: Sáng tạo từ những khối cơ bản (Tiết 3)","yccd":"1. Năng lực mĩ thuật\n- Bước đầu biết cách trang trí đồ vật có sử dụng dạng khối cơ bản.\n- Biết kết hợp các khối cơ bản để tạo nên một sản phẩm mĩ thuật.\n2. Năng lực chung\n- Giao tiếp và hợp tác: Thảo luận nhóm, nhận xét bài của bạn.\n- Giải quyết vấn đề và sáng tạo: Kết hợp khối đơn lẻ tạo sản phẩm.\n3. Phẩm chất\n- Chăm chỉ: Tích cực thực hành.\n- Trách nhiệm: Giữ an toàn, vệ sinh khi dùng công cụ, vật liệu.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 1; sản phẩm mĩ thuật kết hợp từ khối cơ bản; máy chiếu (nếu có).\n- Học sinh: sản phẩm từ tiết 1, 2; đất nặn; vật liệu tái sử dụng dạng khối.","hoatdong":[{"ten":"1. Khởi động","gv":"Mục tiêu: Dẫn vào kết hợp khối.\n- GV cho HS xem một sản phẩm kết hợp từ nhiều khối cơ bản và hỏi: “Sản phẩm này gồm những khối nào?”\n- GV dẫn vào bài.","hs":"- HS trả lời, gọi tên các khối.\n- HS lắng nghe."},{"ten":"2. Khám phá - Thảo luận cách kết hợp khối","gv":"Mục tiêu: Hiểu cách kết hợp khối để tạo sản phẩm.\n- GV chia nhóm cho HS thảo luận theo câu hỏi gợi ý trong SHS.\n- GV phân tích các bước dùng khối cơ bản ghép với nhau để tạo nên một sản phẩm mĩ thuật (SHS trang 47).","hs":"- HS quan sát bài của bạn và trả lời theo nhóm/cá nhân.\n- HS quan sát các bước kết hợp khối và đặt câu hỏi khi chưa hiểu."},{"ten":"3. Luyện tập - Sáng tạo: Kết hợp khối tạo vật","gv":"Mục tiêu: Nặn một vật kết hợp từ một số dạng khối cơ bản.\n- GV cho HS nặn một vật có kết hợp của một số dạng khối cơ bản.\n- GV gợi ý HS xác định khối chính, khối phụ.","hs":"- HS kết hợp khối cơ bản để tạo hình một vật theo ý tưởng của mình."},{"ten":"4. Vận dụng - Giới thiệu sản phẩm","gv":"Mục tiêu: Chia sẻ sản phẩm.\n- GV mời một số HS giới thiệu sản phẩm kết hợp từ khối.\n- GV nhận xét, khen ngợi.","hs":"- HS giới thiệu sản phẩm của mình.\n- HS lắng nghe."}],"status":"checked","source":"KHBD Mĩ thuật 1 KNTT (Bút Xanh) — Chủ đề 6, Tiết 3"},
{"lop":1,"mon":"Mĩ thuật","tuan":20,"tiet":20,"bai":"Chủ đề 6: Sáng tạo từ những khối cơ bản (Tiết 4)","yccd":"1. Năng lực mĩ thuật\n- Tạo được một vật kết hợp từ nhiều khối cơ bản, có tương quan khối chính và khối chi tiết.\n- Trưng bày và giới thiệu được sản phẩm; chia sẻ cảm nhận.\n2. Năng lực chung\n- Giao tiếp và hợp tác: Giới thiệu sản phẩm, nhận xét bài của bạn.\n- Giải quyết vấn đề và sáng tạo: Sắp xếp khối hài hoà.\n3. Phẩm chất\n- Chăm chỉ, trách nhiệm: Hoàn thành và giữ gìn sản phẩm.\n- Yêu nước: Trân trọng sản phẩm của mình và bạn.\n4. Tích hợp\n- Năng lực số 3.2 CB1 (Tích hợp và tinh chỉnh nội dung số): HS nhận ra sản phẩm khối nhìn từ các phía khác nhau qua ba ảnh chụp.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 1; máy chiếu (nếu có).\n- Học sinh: đất nặn/đất sét; vật liệu tái sử dụng dạng khối (nếu có).","hoatdong":[{"ten":"1. Khởi động","gv":"Mục tiêu: Dẫn vào hoàn thiện sản phẩm.\n- GV cho HS nhắc lại vật mình định nặn từ các khối.\n- GV dẫn vào bài.","hs":"- HS nhắc lại ý tưởng của mình.\n- HS lắng nghe."},{"ten":"2. Khám phá - Xem lại tương quan khối chính, khối phụ","gv":"Mục tiêu: Nắm cách sắp xếp khối chính và khối chi tiết.\n- GV nhắc lại cách xác định khối chính và các khối chi tiết trang trí cho khối chính.","hs":"- HS lắng nghe và hình dung cách làm.\n- HS đặt câu hỏi khi chưa hiểu."},{"ten":"3. Luyện tập - Sáng tạo: Hoàn thiện vật từ nhiều khối","gv":"Mục tiêu: Kết hợp nhiều khối cơ bản tạo nên một vật.\n- GV cho HS kết hợp khối cơ bản để tạo hình một vật theo ý tưởng, chú ý tương quan khối chính và khối chi tiết.\n- Mức độ cần đạt: Bắt buộc: tạo được một vật kết hợp từ 2 khối; Khuyến khích: kết hợp nhiều khối, có khối chính và chi tiết.","hs":"- HS kết hợp khối cơ bản để tạo hình một vật, có khối chính và khối chi tiết."},{"ten":"4. Vận dụng - Trưng bày, nhận xét cuối chủ đề","gv":"Mục tiêu: Trưng bày, giới thiệu và nhận xét sản phẩm.\n- GV bày một số sản phẩm của HS trên bảng.\n- GV mời HS giới thiệu sản phẩm theo câu hỏi gợi ý; nhận xét, tổng kết chủ đề.","hs":"- HS bày sản phẩm lên trước mặt.\n- HS giới thiệu sản phẩm của mình theo câu hỏi gợi ý."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV chụp mỗi sản phẩm nặn, ghép của HS từ ba phía trước, bên và trên rồi chiếu ba ảnh cạnh nhau; HS nhận ra sản phẩm khối nhìn từ mỗi phía lại thấy khác nhau, khác với tranh vẽ chỉ nhìn được một mặt.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) HS nói cho bạn nghe nên đặt sản phẩm quay mặt nào ra ngoài khi trưng bày thì đẹp nhất.\n⚠ (Miền 4: An toàn) Đặt sản phẩm lên bàn chắc chắn rồi mới chụp, không cầm sản phẩm giơ lên trước máy vì dễ rơi vỡ; ảnh chỉ dùng cho buổi trưng bày của lớp.","hs":"- HS nhận ra sản phẩm khối nhìn từ các phía khác nhau qua ba ảnh chụp.\n- HS chọn được hướng đặt sản phẩm đẹp nhất khi trưng bày."}],"status":"checked","source":"KHBD Mĩ thuật 1 KNTT (Bút Xanh) — Chủ đề 6, Tiết 4"},
{"lop":1,"mon":"Mĩ thuật","tuan":21,"tiet":21,"bai":"Chủ đề 7: Hoa, quả (Tiết 1)","yccd":"1. Năng lực mĩ thuật\n- Sử dụng được các yếu tố tạo hình đã học để thể hiện một số loại hoa, quả quen thuộc.\n- Nặn được một loại hoa/quả em yêu thích.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động chọn và thể hiện hoa/quả yêu thích.\n- Giao tiếp và hợp tác: Phát biểu về loại hoa, quả mình thích.\n3. Phẩm chất\n- Chăm chỉ: Tích cực thực hành.\n- Yêu nước: Yêu quý cây trái, thiên nhiên quê hương.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS gọi tên và tả được vỏ, màu của các loại quả qua ảnh phóng to.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 1; một số mô hình hoa, quả hoặc hoa, quả thật để HS quan sát; máy chiếu (nếu có).\n- Học sinh: Sách và Vở thực hành Mĩ thuật lớp 1, đồ dùng học tập; hoa, quả sẵn có tại nhà; đất nặn.","hoatdong":[{"ten":"1. Khởi động","gv":"Mục tiêu: Khơi gợi hứng thú với chủ đề hoa, quả.\n- GV cho HS xem một vài loại hoa, quả thật/mô hình và hỏi: “Đây là hoa/quả gì? Màu gì?”\n- GV dẫn vào bài.","hs":"- HS gọi tên hoa, quả và màu sắc.\n- HS lắng nghe."},{"ten":"2. Khám phá - Hình dáng, màu sắc của hoa, quả trong thiên nhiên","gv":"Mục tiêu: Nhận biết hình dáng, màu sắc của một số loại hoa, quả.\n- GV đặt câu hỏi giúp HS quan sát và nhận biết màu sắc của loài hoa, hình dáng, đặc điểm bên ngoài của loại quả.\n- GV lưu ý: Hoa, quả có nhiều hình dáng và màu sắc khác nhau.","hs":"- HS trình bày hiểu biết của mình về hoa, quả.\n- HS lắng nghe và đặt câu hỏi khi chưa hiểu."},{"ten":"3. Luyện tập - Sáng tạo: Nặn hoa/quả em yêu thích","gv":"Mục tiêu: Nặn được một loại hoa/quả em yêu thích.\n- GV mời từng HS phát biểu về loại hoa, quả mình yêu thích và hỏi: sẽ thể hiện màu sắc, hình dáng thế nào?\n- GV cho HS thực hành nặn.","hs":"- HS phát biểu hoa/quả mình yêu thích rồi thực hành nặn từ đất nặn."},{"ten":"4. Vận dụng - Kể về lợi ích của hoa, quả","gv":"Mục tiêu: Liên hệ lợi ích của hoa, quả.\n- GV hỏi HS về lợi ích của hoa, quả trong đời sống.\n- GV nhận xét, khen ngợi.","hs":"- HS kể lợi ích: hoa làm đẹp, quả để ăn, cung cấp vitamin…\n- HS lắng nghe."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu ảnh chụp cận cảnh các loại quả nguyên và quả bổ đôi, phóng to để HS thấy rõ vỏ nhẵn hay sần, màu chuyển từ đậm sang nhạt ở chỗ nào; chiếu thêm ảnh trái cây đặc sản các vùng miền mà ở địa phương mình không có.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS kể tên loại quả có ở quê mình rồi tìm đúng quả đó trong bộ ảnh trên màn hình.\n⚠ (Miền 4: An toàn) GV chọn sẵn ảnh trước giờ học và chỉ mở đúng tập ảnh đó, không tìm ảnh trực tiếp trên mạng trước lớp; xem ảnh xong HS vẫn cầm quả thật để sờ, ngửi và cảm nhận.","hs":"- HS gọi tên và tả được vỏ, màu của các loại quả qua ảnh phóng to.\n- HS kể được loại quả ở quê mình và nhận ra nó trong bộ ảnh."}],"status":"checked","source":"KHBD Mĩ thuật 1 KNTT (Bút Xanh) — Chủ đề 7, Tiết 1"},
{"lop":1,"mon":"Mĩ thuật","tuan":22,"tiet":22,"bai":"Chủ đề 7: Hoa, quả (Tiết 2)","yccd":"1. Năng lực mĩ thuật\n- Biết cách gọi tên các yếu tố được thể hiện trong sản phẩm mĩ thuật về hoa, quả.\n- Tạo hình được hoa/quả theo hình thức tự chọn (vẽ, xé dán, nặn).\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động chọn hình thức thể hiện.\n- Giải quyết vấn đề và sáng tạo: Sắp xếp trước, sau khi thể hiện.\n3. Phẩm chất\n- Chăm chỉ: Kiên trì hoàn thành sản phẩm.\n- Trách nhiệm: Giữ vệ sinh khi thực hành.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 1; một số sản phẩm mĩ thuật theo chủ đề Hoa, quả (tranh vẽ, tranh xé dán, tranh đất nặn đắp nổi); máy chiếu (nếu có).\n- Học sinh: Vở bài tập/giấy A4; màu; giấy màu; vật liệu tái sử dụng; đất nặn.","hoatdong":[{"ten":"1. Khởi động","gv":"Mục tiêu: Ôn lại và dẫn vào bài.\n- GV cho HS xem lại sản phẩm nặn hoa/quả tiết trước và hỏi: “Còn cách nào khác để thể hiện hoa, quả không?”\n- GV dẫn vào bài.","hs":"- HS trả lời: vẽ, xé dán…\n- HS lắng nghe."},{"ten":"2. Khám phá - Hoa, quả trong sản phẩm mĩ thuật","gv":"Mục tiêu: Nhận biết nhiều cách thể hiện chủ đề hoa, quả.\n- GV cho HS quan sát hình minh hoạ trang 52–53, đặt câu hỏi giúp HS nhận biết nhiều cách thể hiện.\n- GV lưu ý: Có nhiều cách để thể hiện chủ đề Hoa, quả.","hs":"- HS trình bày hiểu biết về cách thể hiện chủ đề hoa, quả.\n- HS lắng nghe và đặt câu hỏi khi chưa hiểu."},{"ten":"3. Luyện tập - Sáng tạo: Tạo hình hoa/quả theo hình thức tự chọn","gv":"Mục tiêu: Tạo hình hoa/quả theo hình thức tự chọn.\n- GV mời HS phát biểu sẽ dùng hình thức nào để thực hiện sản phẩm.\n- GV lưu ý: nếu tiết trước đã nặn hoa thì khuyến khích tiết này nặn quả (hoặc ngược lại).\n- Mức độ cần đạt: Bắt buộc: nặn/vẽ được một loại hoa, quả đơn giản; Khuyến khích: tạo sản phẩm có hoa/quả hoàn chỉnh, có hình và nền.","hs":"- HS phát biểu hoa/quả yêu thích rồi thực hành theo cách mình lựa chọn (vẽ, xé dán, nặn)."},{"ten":"4. Vận dụng - Chia sẻ sản phẩm","gv":"Mục tiêu: Giới thiệu sản phẩm.\n- GV mời một số HS giới thiệu hoa/quả mình đã thể hiện.\n- GV nhận xét, khen ngợi.","hs":"- HS giới thiệu sản phẩm của mình.\n- HS lắng nghe."}],"status":"checked","source":"KHBD Mĩ thuật 1 KNTT (Bút Xanh) — Chủ đề 7, Tiết 2"},
{"lop":1,"mon":"Mĩ thuật","tuan":23,"tiet":23,"bai":"Chủ đề 7: Hoa, quả (Tiết 3)","yccd":"1. Năng lực mĩ thuật\n- Biết sử dụng hình ảnh, sắp xếp được vị trí trước, sau khi thực hành theo chủ đề.\n- Thực hiện được thứ tự các bước bày mâm quả.\n2. Năng lực chung\n- Giao tiếp và hợp tác: Thảo luận nhóm, cùng bày mâm quả.\n- Giải quyết vấn đề và sáng tạo: Sắp xếp mâm quả cân đối.\n3. Phẩm chất\n- Chăm chỉ: Tích cực tham gia.\n- Trách nhiệm: Giữ vệ sinh, an toàn khi dùng vật liệu.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 1; quả mô hình; quả thật phù hợp với điều kiện địa phương; máy chiếu (nếu có).\n- Học sinh: sản phẩm từ tiết 1, 2; hoa, quả sẵn có; đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"Mục tiêu: Dẫn vào bày mâm quả.\n- GV cho HS xem một mâm quả đẹp và hỏi: “Các quả được sắp xếp thế nào?”\n- GV dẫn vào bài.","hs":"- HS trả lời: quả to ở dưới, quả nhỏ ở trên…\n- HS lắng nghe."},{"ten":"2. Khám phá - Thảo luận về cách bày mâm quả","gv":"Mục tiêu: Nhận biết cách bày mâm quả.\n- GV chia nhóm cho HS thảo luận theo câu hỏi gợi ý trong SGV.\n- GV đặt câu hỏi để HS nhận biết về cách bày mâm quả (SHS trang 55); lưu ý: bày quả to trước, quả nhỏ tạo điểm nhấn và sắp xếp cho cân đối.","hs":"- HS quan sát và trả lời theo nhóm/cá nhân.\n- HS lắng nghe và đặt câu hỏi khi chưa hiểu."},{"ten":"3. Luyện tập - Sáng tạo: Bày mâm quả","gv":"Mục tiêu: Thực hiện các bước bày mâm quả.\n- GV mời nhóm HS lựa chọn kiểu bày và bày mâm quả theo gợi ý trong SHS.\n- GV quan sát, hỗ trợ các nhóm.","hs":"- HS bày mâm quả theo nhóm.\n- HS sắp xếp quả to trước, quả nhỏ tạo điểm nhấn."},{"ten":"4. Vận dụng - Chia sẻ mâm quả","gv":"Mục tiêu: Giới thiệu mâm quả của nhóm.\n- GV mời các nhóm giới thiệu mâm quả.\n- GV nhận xét, khen ngợi; nói về lợi ích của hoa, quả trong đời sống.","hs":"- HS giới thiệu mâm quả của nhóm mình.\n- HS lắng nghe."}],"status":"checked","source":"KHBD Mĩ thuật 1 KNTT (Bút Xanh) — Chủ đề 7, Tiết 3"},
{"lop":1,"mon":"Mĩ thuật","tuan":24,"tiet":24,"bai":"Chủ đề 7: Hoa, quả (Tiết 4)","yccd":"1. Năng lực mĩ thuật\n- Vẽ hoặc xé dán được mâm quả đã bày.\n- Trưng bày và chia sẻ được cảm nhận về sản phẩm.\n2. Năng lực chung\n- Giao tiếp và hợp tác: Giới thiệu sản phẩm, nhận xét bài của bạn.\n- Giải quyết vấn đề và sáng tạo: Thể hiện lại mâm quả có tương quan hình và nền.\n3. Phẩm chất\n- Chăm chỉ, trách nhiệm: Hoàn thành và giữ gìn sản phẩm.\n- Yêu nước: Trân trọng sản vật quê hương.\n4. Tích hợp\n- Năng lực số 3.2 CB1 (Tích hợp và tinh chỉnh nội dung số): HS xem phòng tranh trên màn hình và nhận ra tên tác giả ghi dưới mỗi bức.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 1; máy chiếu (nếu có).\n- Học sinh: Vở bài tập/giấy A4; màu; giấy màu.","hoatdong":[{"ten":"1. Khởi động","gv":"Mục tiêu: Dẫn vào vẽ/xé dán mâm quả.\n- GV cho HS nhớ lại mâm quả nhóm mình đã bày ở tiết trước.\n- GV dẫn vào bài.","hs":"- HS nhớ lại mâm quả đã bày.\n- HS lắng nghe."},{"ten":"2. Khám phá - Cách thể hiện lại mâm quả","gv":"Mục tiêu: Nắm cách vẽ/xé dán lại mâm quả.\n- GV gợi ý HS chọn hình thức phù hợp (vẽ hoặc xé dán) để thể hiện lại mâm quả đã bày.\n- GV bày mâm quả ở vị trí thuận tiện cho HS quan sát.","hs":"- HS lắng nghe và lựa chọn hình thức thể hiện.\n- HS quan sát mâm quả mẫu."},{"ten":"3. Luyện tập - Sáng tạo: Vẽ/xé dán mâm quả","gv":"Mục tiêu: Thể hiện lại mâm quả bằng vẽ hoặc xé dán.\n- GV cho HS lựa chọn hình thức phù hợp thể hiện lại mâm quả vào Vở bài tập/giấy A4.\n- Mức độ cần đạt: Bắt buộc: tạo hình mâm quả đơn giản; Khuyến khích: thể hiện được đặc điểm bên ngoài khác nhau của các loại quả.","hs":"- HS thể hiện lại mâm quả vào Vở bài tập/giấy A4 bằng hình thức đã chọn."},{"ten":"4. Vận dụng - Trưng bày, nhận xét cuối chủ đề","gv":"Mục tiêu: Trưng bày, giới thiệu và nhận xét sản phẩm.\n- GV bày một số sản phẩm của HS trên bảng.\n- GV đặt câu hỏi gợi ý để HS giới thiệu sản phẩm mâm quả; nhận xét, tổng kết chủ đề.","hs":"- HS bày sản phẩm lên trước mặt.\n- HS giới thiệu sản phẩm của mình theo câu hỏi gợi ý."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV chụp tranh mâm quả của cả lớp, ghép thành một phòng tranh xếp theo hàng như tường triển lãm, dưới mỗi tranh ghi tên bạn đã vẽ; GV chỉ cho HS thấy tên tác giả luôn được ghi dưới mỗi bức tranh trong triển lãm thật cũng như trong phòng tranh của lớp.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) HS đi “tham quan” phòng tranh trên màn hình, chọn một bức không phải của mình và nói một điều mình thích ở bức đó.\n⚠ (Miền 4: An toàn) Tranh của bạn nào thì ghi tên bạn ấy, không được chiếu tranh của bạn rồi nhận là mình vẽ; phòng tranh chỉ chiếu trong lớp học.","hs":"- HS xem phòng tranh trên màn hình và nhận ra tên tác giả ghi dưới mỗi bức.\n- HS nêu được điều mình thích ở tranh của bạn."}],"status":"checked","source":"KHBD Mĩ thuật 1 KNTT (Bút Xanh) — Chủ đề 7, Tiết 4"},
{"lop":1,"mon":"Mĩ thuật","tuan":25,"tiet":25,"bai":"Chủ đề 8: Người thân của em (Tiết 1)","yccd":"1. Năng lực mĩ thuật\n- Biết tìm ý tưởng thể hiện chủ đề Người thân của em qua quan sát hình ảnh từ cuộc sống.\n- Vẽ được hình ảnh người thân trong gia đình.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động nhớ lại và kể về người thân.\n- Giao tiếp và hợp tác: Chia sẻ kỉ niệm với người thân.\n3. Phẩm chất\n- Nhân ái: Yêu thương, biết ơn người thân trong gia đình.\n- Chăm chỉ: Tích cực thực hành.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS chỉ ra được nét riêng của từng người trong tranh chân dung phóng to.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 1; một số ảnh chụp, bức tranh, bài hát, bài thơ ngắn về chủ đề gia đình, người thân; máy chiếu (nếu có).\n- Học sinh: Sách và Vở thực hành Mĩ thuật lớp 1, đồ dùng học tập; ảnh chụp về người thân trong gia đình.","hoatdong":[{"ten":"1. Khởi động","gv":"Mục tiêu: Khơi gợi tình cảm với người thân.\n- GV cho HS nghe một bài hát ngắn về gia đình và hỏi: “Bài hát nói về ai?”\n- GV dẫn vào bài.","hs":"- HS trả lời: về ông bà, bố mẹ, gia đình.\n- HS lắng nghe."},{"ten":"2. Khám phá - Tìm hiểu hình ảnh về người thân","gv":"Mục tiêu: Mô tả hình ảnh về người thân của em.\n- GV đặt câu hỏi giúp HS kể về một số kỉ niệm đáng nhớ với người thân trong gia đình.\n- GV lưu ý: Có rất nhiều hình ảnh để thể hiện người thân trong gia đình.","hs":"- HS trình bày theo câu hỏi gợi ý của GV.\n- HS kể kỉ niệm với người thân."},{"ten":"3. Luyện tập - Sáng tạo: Vẽ về người thân của em","gv":"Mục tiêu: Vẽ hình ảnh người thân trong gia đình.\n- GV cho HS thực hiện hoạt động vẽ để thể hiện hình ảnh người thân trong gia đình vào Vở bài tập/giấy A4.\n- GV quan sát, hỗ trợ HS.","hs":"- HS thực hiện vẽ người thân vào Vở bài tập/giấy A4."},{"ten":"4. Vận dụng - Giới thiệu người thân trong tranh","gv":"Mục tiêu: Chia sẻ về người thân đã vẽ.\n- GV mời một số HS giới thiệu người thân mình đã vẽ.\n- GV nhận xét, khen ngợi.","hs":"- HS giới thiệu người thân đã vẽ.\n- HS lắng nghe."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu bộ tranh chân dung và tranh gia đình đã chuẩn bị sẵn, phóng to phần khuôn mặt để HS thấy người vẽ đã tả mái tóc, đôi mắt, nụ cười của từng người khác nhau ra sao.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS nhớ lại và tả bằng lời một nét riêng của người thân mình như tóc bạc, đeo kính, có râu, trước khi bắt tay vào vẽ.\n⚠ (Miền 4: An toàn) GV chỉ dùng tranh, ảnh đã chuẩn bị sẵn; không chiếu ảnh chụp gia đình của bất kì bạn nào lên màn hình khi gia đình bạn chưa cho phép.","hs":"- HS chỉ ra được nét riêng của từng người trong tranh chân dung phóng to.\n- HS tả được bằng lời một nét riêng của người thân mình."}],"status":"checked","source":"KHBD Mĩ thuật 1 KNTT (Bút Xanh) — Chủ đề 8, Tiết 1"},
{"lop":1,"mon":"Mĩ thuật","tuan":26,"tiet":26,"bai":"Chủ đề 8: Người thân của em (Tiết 2)","yccd":"1. Năng lực mĩ thuật\n- Biết sử dụng hình ảnh, sắp xếp vị trí trước, sau để thể hiện chủ đề Người thân của em.\n- Thể hiện được một sản phẩm mĩ thuật về chủ đề người thân theo cách mình yêu thích.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động chọn hình thức thể hiện.\n- Giải quyết vấn đề và sáng tạo: Sắp xếp hình ảnh trước, sau.\n3. Phẩm chất\n- Nhân ái: Yêu thương người thân.\n- Chăm chỉ: Kiên trì hoàn thành sản phẩm.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 1; một số sản phẩm mĩ thuật theo chủ đề gia đình (tranh vẽ, tranh xé dán, tranh đất nặn đắp nổi); máy chiếu (nếu có).\n- Học sinh: đồ dùng học tập; vật liệu tái sử dụng; Vở bài tập/giấy A4; màu; giấy màu.","hoatdong":[{"ten":"1. Khởi động","gv":"Mục tiêu: Ôn lại và dẫn vào bài.\n- GV cho HS xem lại tranh vẽ người thân tiết trước và hỏi: “Còn cách nào khác để thể hiện người thân không?”\n- GV dẫn vào bài.","hs":"- HS trả lời: xé dán, nặn…\n- HS lắng nghe."},{"ten":"2. Khám phá - Cách thể hiện hình ảnh người thân","gv":"Mục tiêu: Nhận biết nhiều cách thể hiện chủ đề.\n- GV cho HS quan sát hình minh hoạ trang 58, đặt câu hỏi giúp HS nhận biết nhiều cách thể hiện.\n- GV lưu ý: Có rất nhiều cách để thể hiện người thân trong gia đình.","hs":"- HS quan sát và đặt câu hỏi khi chưa hiểu.\n- HS nêu các cách thể hiện mình biết."},{"ten":"3. Luyện tập - Sáng tạo: Thể hiện sản phẩm về người thân","gv":"Mục tiêu: Thể hiện một sản phẩm mĩ thuật về chủ đề người thân theo cách yêu thích.\n- GV mời HS phát biểu sẽ dùng hình thức nào để thực hiện.\n- GV cho HS thể hiện một sản phẩm mĩ thuật về chủ đề người thân theo cách mình yêu thích.","hs":"- HS thực hiện theo cách mình lựa chọn (vẽ, xé dán, nặn)."},{"ten":"4. Vận dụng - Chia sẻ sản phẩm","gv":"Mục tiêu: Giới thiệu sản phẩm.\n- GV mời một số HS giới thiệu sản phẩm.\n- GV nói về lợi ích của sự gắn kết, chia sẻ giữa các thành viên trong gia đình.","hs":"- HS giới thiệu sản phẩm của mình.\n- HS lắng nghe."}],"status":"checked","source":"KHBD Mĩ thuật 1 KNTT (Bút Xanh) — Chủ đề 8, Tiết 2"},
{"lop":1,"mon":"Mĩ thuật","tuan":27,"tiet":27,"bai":"Chủ đề 8: Người thân của em (Tiết 3)","yccd":"1. Năng lực mĩ thuật\n- Biết vận dụng kĩ năng đã học để trang trí một tấm bưu thiếp tặng người thân.\n- Vẽ được ý tưởng trang trí tấm thiếp.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động lên ý tưởng làm thiếp.\n- Giải quyết vấn đề và sáng tạo: Sử dụng vật liệu sẵn có để trang trí thiếp.\n3. Phẩm chất\n- Nhân ái: Thể hiện tình cảm với người thân qua tấm thiệp.\n- Chăm chỉ: Tích cực thực hành.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 1; một số mẫu thiếp chúc mừng; máy chiếu (nếu có).\n- Học sinh: đồ dùng học tập; Vở bài tập/giấy A4; màu; giấy màu; vật liệu làm thiếp.","hoatdong":[{"ten":"1. Khởi động","gv":"Mục tiêu: Dẫn vào làm thiếp.\n- GV cho HS xem một tấm thiếp đẹp và hỏi: “Tấm thiếp này để làm gì? Tặng ai?”\n- GV dẫn vào bài.","hs":"- HS trả lời: thiếp để chúc mừng, tặng người thân.\n- HS lắng nghe."},{"ten":"2. Khám phá - Tìm hiểu các bước làm thiếp","gv":"Mục tiêu: Nhận biết các loại thiếp và các bước làm thiếp.\n- GV đặt câu hỏi để HS nhận biết về các loại thiếp (SHS hoặc thiếp đã chuẩn bị).\n- GV phân tích và đặt câu hỏi về các bước thực hiện một tấm thiếp (SHS trang 62–63); lưu ý: có nhiều cách làm thiếp, làm từ phần chung rồi đến các chi tiết trang trí.","hs":"- HS quan sát và trả lời câu hỏi.\n- HS đặt câu hỏi khi chưa hiểu."},{"ten":"3. Luyện tập - Sáng tạo: Vẽ ý tưởng và trang trí tấm thiếp","gv":"Mục tiêu: Vẽ ý tưởng và trang trí tấm thiếp.\n- GV cho HS vẽ ý tưởng và trang trí tấm thiếp vào Vở bài tập trang 43/giấy A4, trước khi làm thiếp bằng vật liệu tự chọn.\n- GV quan sát, hỗ trợ.","hs":"- HS vẽ ý tưởng và trang trí tấm thiếp vào Vở bài tập/giấy A4."},{"ten":"4. Vận dụng - Chia sẻ ý tưởng thiếp","gv":"Mục tiêu: Trình bày ý tưởng làm thiếp.\n- GV mời một số HS giới thiệu ý tưởng thiếp và người mình muốn tặng.\n- GV nhận xét, dặn HS chuẩn bị vật liệu cho tiết sau.","hs":"- HS giới thiệu ý tưởng thiếp của mình.\n- HS lắng nghe."}],"status":"checked","source":"KHBD Mĩ thuật 1 KNTT (Bút Xanh) — Chủ đề 8, Tiết 3"},
{"lop":1,"mon":"Mĩ thuật","tuan":28,"tiet":28,"bai":"Chủ đề 8: Người thân của em (Tiết 4)","yccd":"1. Năng lực mĩ thuật\n- Làm được một tấm thiếp bằng vật liệu tự chọn để tặng người thân.\n- Trưng bày và chia sẻ được cảm nhận về sản phẩm.\n2. Năng lực chung\n- Giao tiếp và hợp tác: Giới thiệu sản phẩm, nhận xét bài của bạn.\n- Giải quyết vấn đề và sáng tạo: Sử dụng công cụ an toàn, phù hợp vật liệu.\n3. Phẩm chất\n- Nhân ái: Thể hiện tình cảm qua tấm thiệp tặng người thân.\n- Chăm chỉ, trách nhiệm: Hoàn thành và giữ gìn sản phẩm.\n4. Tích hợp\n- Năng lực số 2.5 CB1 (Nghi thức giao tiếp trong môi trường số): HS nói và viết được lời chúc lễ phép cho người thân.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 1; máy chiếu (nếu có).\n- Học sinh: vật liệu phù hợp với hình thức làm thiếp; kéo an toàn; keo; màu; giấy màu.","hoatdong":[{"ten":"1. Khởi động","gv":"Mục tiêu: Dẫn vào hoàn thiện thiếp.\n- GV cho HS nhắc lại ý tưởng thiếp đã vẽ ở tiết trước.\n- GV dẫn vào bài.","hs":"- HS nhắc lại ý tưởng của mình.\n- HS lắng nghe."},{"ten":"2. Khám phá - Xem lại cách làm thiếp an toàn","gv":"Mục tiêu: Nắm cách làm thiếp và sử dụng công cụ an toàn.\n- GV nhắc lại các bước làm thiếp; lưu ý HS sử dụng kéo, keo an toàn.","hs":"- HS lắng nghe và hình dung cách làm.\n- HS đặt câu hỏi khi chưa hiểu."},{"ten":"3. Luyện tập - Sáng tạo: Làm tấm thiếp tặng người thân","gv":"Mục tiêu: Làm một tấm thiếp bằng vật liệu tự chọn.\n- GV quan sát và hỗ trợ đối với từng trường hợp HS làm thiếp theo gợi ý trong SGV.\n- Mức độ cần đạt: Bắt buộc: tạo và trang trí được một tấm thiếp đơn giản; Khuyến khích: trang trí hài hoà; Tuỳ ý: viết được lời chúc phù hợp.","hs":"- HS lựa chọn hình thức phù hợp thể hiện tấm thiếp."},{"ten":"4. Vận dụng - Trưng bày, nhận xét cuối chủ đề","gv":"Mục tiêu: Trưng bày, giới thiệu và nhận xét sản phẩm.\n- GV bày một số sản phẩm của HS trên bảng.\n- GV đặt câu hỏi gợi ý để HS giới thiệu tấm thiếp và người mình muốn tặng; nhận xét, tổng kết chủ đề.","hs":"- HS bày sản phẩm lên trước mặt.\n- HS giới thiệu sản phẩm của mình theo câu hỏi gợi ý."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) GV chụp tấm thiếp của HS, chiếu lên màn hình và hướng dẫn cả lớp tập nói lời chúc lễ phép, ngắn gọn để ghi vào thiếp; GV làm mẫu cách người lớn gửi một tấm thiếp bằng tin nhắn cho người thân ở xa.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) HS đọc to lời chúc của mình, cả lớp nghe và giúp bạn sửa cho lời chúc rõ ý và lễ phép hơn.\n⚠ (Miền 4: An toàn) Việc gửi tin nhắn do người lớn trong nhà làm giúp, HS chưa tự nhắn tin và chưa dùng điện thoại một mình; không nhắn tin cho người mình không quen biết.","hs":"- HS nói và viết được lời chúc lễ phép cho người thân.\n- HS biết muốn gửi thiếp qua tin nhắn thì phải nhờ người lớn."}],"status":"checked","source":"KHBD Mĩ thuật 1 KNTT (Bút Xanh) — Chủ đề 8, Tiết 4"},
{"lop":1,"mon":"Mĩ thuật","tuan":29,"tiet":29,"bai":"Chủ đề 9: Em là học sinh lớp 1 (Tiết 1)","yccd":"1. Năng lực mĩ thuật\n- Sử dụng được các yếu tố tạo hình đã học để thể hiện một số cảnh, vật xung quanh HS.\n- Vẽ được cảnh/vật thể hiện chủ đề Em là học sinh lớp Một.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động kể về hoạt động ở trường.\n- Giao tiếp và hợp tác: Chia sẻ hình ảnh quen thuộc từ nhà đến trường.\n3. Phẩm chất\n- Chăm chỉ: Tích cực thực hành.\n- Yêu nước: Yêu quý trường lớp, thầy cô, bạn bè.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS kể được các hoạt động ở trường sau khi xem lại đoạn phim.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 1; một số ảnh chụp, bức tranh, bài hát, bài thơ ngắn về chủ đề nhà trường; máy chiếu (nếu có).\n- Học sinh: Sách và Vở thực hành Mĩ thuật lớp 1, đồ dùng học tập; một món đồ thân thuộc trong năm học đã cũ.","hoatdong":[{"ten":"1. Khởi động","gv":"Mục tiêu: Khơi gợi tình cảm với trường lớp.\n- GV cho HS hát/nghe một bài hát về trường lớp và hỏi: “Ở trường, em thích làm gì nhất?”\n- GV dẫn vào bài.","hs":"- HS trả lời về hoạt động em thích ở trường.\n- HS lắng nghe."},{"ten":"2. Khám phá - Tìm hiểu hình ảnh liên quan đến chủ đề","gv":"Mục tiêu: Kể, mô tả hình ảnh quen thuộc từ nhà đến trường.\n- GV đặt câu hỏi giúp HS kể về những hình ảnh quen thuộc từ nhà đến trường.\n- GV đặt câu hỏi giúp HS kể về những hoạt động và nhân vật ở trường.","hs":"- HS trình bày theo câu hỏi gợi ý của GV.\n- HS kể hoạt động, nhân vật ở trường."},{"ten":"3. Luyện tập - Sáng tạo: Vẽ chủ đề Em là học sinh lớp Một","gv":"Mục tiêu: Vẽ cảnh/vật thể hiện chủ đề.\n- GV yêu cầu HS thể hiện hình ảnh/nhân vật ở trường vừa phát biểu vào Vở bài tập/giấy A4.\n- HS có thể tham khảo thêm hình ảnh ở Vở bài tập trang 44.","hs":"- HS thực hiện vào Vở bài tập/giấy A4."},{"ten":"4. Vận dụng - Giới thiệu bức tranh trường em","gv":"Mục tiêu: Chia sẻ về bức tranh đã vẽ.\n- GV mời một số HS giới thiệu bức tranh của mình.\n- GV nhận xét, khen ngợi.","hs":"- HS giới thiệu bức tranh của mình.\n- HS lắng nghe."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu đoạn phim ngắn quay lại một buổi ra chơi, buổi chào cờ, giờ học của chính lớp mình; HS xem lại được cả những khoảnh khắc mình không nhìn thấy lúc đang chơi, nhờ đó nhớ ra chi tiết để đưa vào tranh.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV dừng phim ở một cảnh và cùng HS đếm trong cảnh đó có mấy bạn, các bạn đang làm gì, sân trường có những gì.\n⚠ (Miền 4: An toàn) Phim do GV quay và giữ trong máy của lớp, không đưa lên mạng; nếu có bạn không muốn hình mình xuất hiện thì GV bỏ cảnh đó ra.","hs":"- HS kể được các hoạt động ở trường sau khi xem lại đoạn phim.\n- HS nêu được chi tiết mình sẽ đưa vào tranh."}],"status":"checked","source":"KHBD Mĩ thuật 1 KNTT (Bút Xanh) — Chủ đề 9, Tiết 1"},
{"lop":1,"mon":"Mĩ thuật","tuan":30,"tiet":30,"bai":"Chủ đề 9: Em là học sinh lớp 1 (Tiết 2)","yccd":"1. Năng lực mĩ thuật\n- Biết cách gọi tên các yếu tố tạo hình được thể hiện trong sản phẩm.\n- Thể hiện được một sản phẩm mĩ thuật về chủ đề Em là học sinh lớp Một theo cách yêu thích.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động chọn hình thức thể hiện.\n- Giải quyết vấn đề và sáng tạo: Sắp xếp chính, phụ trong tranh.\n3. Phẩm chất\n- Chăm chỉ: Kiên trì hoàn thành sản phẩm.\n- Yêu nước: Yêu quý trường lớp, bạn bè.\n4. Tích hợp\n- Năng lực số 6.1 CB1 (Hiểu biết về trí tuệ nhân tạo): HS chỉ ra được chỗ máy vẽ chưa đúng trong bức hình do máy tạo.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 1; một số sản phẩm mĩ thuật theo chủ đề nhà trường (tranh vẽ, tranh xé dán, tranh đất nặn đắp nổi); máy chiếu (nếu có).\n- Học sinh: đồ dùng học tập; vật liệu phù hợp với hình thức lựa chọn; Vở bài tập/giấy A4; màu.","hoatdong":[{"ten":"1. Khởi động","gv":"Mục tiêu: Ôn lại và dẫn vào bài.\n- GV cho HS xem lại tranh tiết trước và hỏi: “Còn cách nào khác để thể hiện chủ đề không?”\n- GV dẫn vào bài.","hs":"- HS trả lời: xé dán, nặn…\n- HS lắng nghe."},{"ten":"2. Khám phá - Cách thể hiện chủ đề qua tranh","gv":"Mục tiêu: Nhận biết nhiều cách thể hiện chủ đề.\n- GV cho HS quan sát hình minh hoạ trang 67, đặt câu hỏi giúp HS nhận biết nhiều cách thể hiện.\n- GV lưu ý có nhiều ý tưởng, cách thể hiện về chủ đề.","hs":"- HS quan sát và đặt câu hỏi khi chưa hiểu.\n- HS nêu các cách thể hiện mình biết."},{"ten":"3. Luyện tập - Sáng tạo: Thể hiện sản phẩm về chủ đề","gv":"Mục tiêu: Thể hiện một sản phẩm mĩ thuật về chủ đề theo cách yêu thích.\n- GV cho HS lựa chọn hình thức yêu thích thể hiện về chủ đề này.\n- Mức độ cần đạt: Bắt buộc: vẽ được cảnh/vật thể hiện chủ đề; Khuyến khích: có sắp xếp chính phụ; Tuỳ ý: kết hợp màu sắc hài hoà giữa hình và nền.","hs":"- HS thực hiện theo hình thức mình lựa chọn."},{"ten":"4. Vận dụng - Chia sẻ sản phẩm","gv":"Mục tiêu: Giới thiệu sản phẩm.\n- GV mời một số HS giới thiệu sản phẩm.\n- GV nói về lợi ích của các hoạt động trong nhà trường, giúp HS vui vẻ mỗi ngày đến trường.","hs":"- HS giới thiệu sản phẩm của mình.\n- HS lắng nghe."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 1) GV mở công cụ tạo hình bằng trí tuệ nhân tạo, gõ câu “sân trường có các bạn nhỏ đang chơi” cho máy vẽ ra hai, ba bức khác nhau; cả lớp cùng tìm chỗ máy vẽ sai như bàn tay thừa ngón, chữ trên bảng không đọc được, để hiểu máy vẽ nhanh nhưng không phải lúc nào cũng đúng.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS so sánh bức máy vẽ với đoạn phim quay sân trường mình đã xem và chỉ ra cái gì có thật ở trường mình mà máy không vẽ được.\n⚠ (Miền 4: An toàn) Chỉ cô giáo gõ chữ và bấm máy; hình do máy vẽ chỉ để xem và nhận xét, các em không chép lại thành bài của mình vì bài phải do chính em vẽ.","hs":"- HS chỉ ra được chỗ máy vẽ chưa đúng trong bức hình do máy tạo.\n- HS nêu được điều riêng của trường mình mà máy không biết."}],"status":"checked","source":"KHBD Mĩ thuật 1 KNTT (Bút Xanh) — Chủ đề 9, Tiết 2"},
{"lop":1,"mon":"Mĩ thuật","tuan":31,"tiet":31,"bai":"Chủ đề 9: Em là học sinh lớp 1 (Tiết 3)","yccd":"1. Năng lực mĩ thuật\n- Sử dụng được màu sắc, hình vẽ và vật liệu sẵn có để trang trí một món đồ dùng học tập.\n- Vẽ được ý tưởng trang trí một món đồ dùng thường sử dụng khi đi học.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động lên ý tưởng trang trí.\n- Giải quyết vấn đề và sáng tạo: Sử dụng yếu tố tạo hình để trang trí.\n3. Phẩm chất\n- Chăm chỉ: Tích cực thực hành.\n- Trách nhiệm: Giữ gìn đồ dùng học tập.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 1; máy chiếu (nếu có).\n- Học sinh: Vở bài tập/giấy A4; một món đồ thân thuộc trong năm học đã cũ; màu; đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"Mục tiêu: Dẫn vào trang trí đồ dùng học tập.\n- GV cho HS xem một chiếc túi giấy đựng bài kiểm tra được trang trí đẹp và hỏi cách trang trí.\n- GV dẫn vào bài.","hs":"- HS trả lời: dùng màu, hình vẽ để trang trí.\n- HS lắng nghe."},{"ten":"2. Khám phá - Các bước trang trí đồ dùng","gv":"Mục tiêu: Nhận biết cách trang trí một món đồ.\n- GV đặt câu hỏi để HS có ý thức về việc trang trí một món đồ cũ và gợi ý cách thực hiện.\n- GV phân tích và đặt câu hỏi về các bước thực hiện trang trí một chiếc túi giấy đựng bài kiểm tra (SHS trang 70); lưu ý: có nhiều cách để trang trí một món đồ cũ.","hs":"- HS quan sát và trả lời câu hỏi.\n- HS đặt câu hỏi khi chưa hiểu."},{"ten":"3. Luyện tập - Sáng tạo: Vẽ ý tưởng trang trí đồ dùng","gv":"Mục tiêu: Vẽ ý tưởng trang trí một món đồ dùng học tập.\n- GV cho HS vẽ ý tưởng trang trí vào Vở bài tập trang 47/giấy A4.\n- GV gợi ý HS chọn hình, màu để trang trí.","hs":"- HS thực hiện vẽ ý tưởng vào Vở bài tập/giấy A4."},{"ten":"4. Vận dụng - Chia sẻ ý tưởng","gv":"Mục tiêu: Trình bày ý tưởng trang trí.\n- GV mời một số HS giới thiệu ý tưởng của mình.\n- GV nhận xét, dặn HS chuẩn bị món đồ và vật liệu cho tiết sau.","hs":"- HS giới thiệu ý tưởng trang trí của mình.\n- HS lắng nghe."}],"status":"checked","source":"KHBD Mĩ thuật 1 KNTT (Bút Xanh) — Chủ đề 9, Tiết 3"},
{"lop":1,"mon":"Mĩ thuật","tuan":32,"tiet":32,"bai":"Chủ đề 9: Em là học sinh lớp 1 (Tiết 4)","yccd":"1. Năng lực mĩ thuật\n- Trang trí được một món đồ dùng thường sử dụng khi đi học.\n- Trưng bày và chia sẻ được cảm nhận về sản phẩm của cá nhân, nhóm.\n2. Năng lực chung\n- Giao tiếp và hợp tác: Giới thiệu sản phẩm, nhận xét bài của bạn.\n- Giải quyết vấn đề và sáng tạo: Sử dụng công cụ an toàn, phù hợp vật liệu.\n3. Phẩm chất\n- Chăm chỉ, trách nhiệm: Hoàn thành, giữ gìn sản phẩm và đồ dùng học tập.\n- Yêu nước: Trân trọng sản phẩm của mình và bạn.\n4. Tích hợp\n- Năng lực số 3.2 CB1 (Tích hợp và tinh chỉnh nội dung số): HS xem bộ ảnh trên màn hình và nhận ra món đồ của mình.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 1; máy chiếu (nếu có).\n- Học sinh: món đồ cũ đã chuẩn bị; vật liệu phù hợp với hình thức trang trí; màu; kéo an toàn; keo.","hoatdong":[{"ten":"1. Khởi động","gv":"Mục tiêu: Dẫn vào thực hành trang trí.\n- GV cho HS nhắc lại ý tưởng trang trí đã vẽ ở tiết trước.\n- GV dẫn vào bài.","hs":"- HS nhắc lại ý tưởng của mình.\n- HS lắng nghe."},{"ten":"2. Khám phá - Xem lại cách trang trí an toàn","gv":"Mục tiêu: Nắm cách trang trí và sử dụng công cụ an toàn.\n- GV nhắc lại cách trang trí món đồ; lưu ý HS sử dụng kéo, keo an toàn.","hs":"- HS lắng nghe và hình dung cách làm.\n- HS đặt câu hỏi khi chưa hiểu."},{"ten":"3. Luyện tập - Sáng tạo: Trang trí món đồ dùng học tập","gv":"Mục tiêu: Trang trí một món đồ thường sử dụng khi đi học.\n- GV quan sát và hỗ trợ đối với từng trường hợp HS.\n- Mức độ cần đạt: Bắt buộc: trang trí một mặt của món đồ; Khuyến khích: trang trí nhiều mặt; Tuỳ ý: sử dụng yếu tố tạo hình hài hoà với món đồ.","hs":"- HS lựa chọn hình thức phù hợp để trang trí món đồ."},{"ten":"4. Vận dụng - Trưng bày, nhận xét cuối chủ đề","gv":"Mục tiêu: Trưng bày, giới thiệu và nhận xét sản phẩm.\n- GV bày một số sản phẩm của HS trên bảng.\n- GV đặt câu hỏi gợi ý để HS giới thiệu cách trang trí món đồ; nhận xét, tổng kết chủ đề.","hs":"- HS bày sản phẩm lên trước mặt.\n- HS giới thiệu sản phẩm của mình theo câu hỏi gợi ý."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV chụp món đồ dùng học tập đã trang trí của từng HS, xếp thành bộ ảnh chiếu lên màn hình và ghi tên bạn làm ra món đồ dưới mỗi ảnh.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) HS nói cho bạn nghe mình đã trang trí món đồ ấy bằng hình gì, màu gì và dùng nó vào việc gì.\n⚠ (Miền 4: An toàn) Chỉ chụp món đồ, không chụp cặp sách hay đồ dùng có ghi họ tên đầy đủ và địa chỉ của HS; bộ ảnh chỉ chiếu trong lớp.","hs":"- HS xem bộ ảnh trên màn hình và nhận ra món đồ của mình.\n- HS giới thiệu được cách mình trang trí món đồ dùng học tập."}],"status":"checked","source":"KHBD Mĩ thuật 1 KNTT (Bút Xanh) — Chủ đề 9, Tiết 4"},
{"lop":1,"mon":"Mĩ thuật","tuan":33,"tiet":33,"bai":"Trưng bày sản phẩm cuối năm (Tiết 1)","yccd":"1. Năng lực mĩ thuật\n- Hệ thống lại được các yếu tố tạo hình đã học trong năm (chấm, nét, hình, khối, màu).\n- Lựa chọn và chuẩn bị được sản phẩm mĩ thuật tiêu biểu của mình để trưng bày.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động lựa chọn, sắp xếp sản phẩm.\n- Giao tiếp và hợp tác: Trao đổi, chia sẻ với bạn về sản phẩm.\n3. Phẩm chất\n- Chăm chỉ, trách nhiệm: Giữ gìn sản phẩm cả năm.\n- Yêu nước: Trân trọng thành quả học tập của mình và bạn.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 1; máy chiếu (nếu có); dây, kẹp/băng dính để treo sản phẩm.\n- Học sinh: các sản phẩm mĩ thuật đã làm trong năm học.","hoatdong":[{"ten":"1. Khởi động","gv":"Mục tiêu: Ôn lại các yếu tố tạo hình đã học.\n- GV cho HS xem nhanh lại các chủ đề đã học (chấm, nét, hình, khối, màu) và hỏi: “Cả năm chúng ta đã học được những gì?”\n- GV dẫn vào bài.","hs":"- HS kể tên các yếu tố tạo hình đã học.\n- HS lắng nghe."},{"ten":"2. Khám phá - Lựa chọn sản phẩm tiêu biểu","gv":"Mục tiêu: Chọn sản phẩm để trưng bày.\n- GV hướng dẫn HS xem lại các sản phẩm cả năm, chọn ra 1–2 sản phẩm mình thích nhất.\n- GV gợi ý HS lí do chọn sản phẩm đó.","hs":"- HS xem lại và chọn sản phẩm tiêu biểu.\n- HS nêu lí do chọn."},{"ten":"3. Luyện tập - Chuẩn bị trưng bày theo nhóm","gv":"Mục tiêu: Sắp xếp sản phẩm để trưng bày.\n- GV chia nhóm, hướng dẫn HS sắp xếp sản phẩm gọn gàng, đẹp mắt theo nhóm.\n- GV gợi ý cách trang trí góc trưng bày của nhóm.","hs":"- HS cùng nhóm sắp xếp sản phẩm trưng bày.\n- HS trang trí góc trưng bày."},{"ten":"4. Vận dụng - Đặt tên cho góc trưng bày","gv":"Mục tiêu: Sáng tạo tên gọi cho phần trưng bày.\n- GV cho các nhóm đặt tên cho góc trưng bày của mình.\n- GV nhận xét, khen ngợi.","hs":"- HS thảo luận và đặt tên cho góc trưng bày.\n- HS lắng nghe."}],"status":"checked","source":"KHBD Mĩ thuật 1 KNTT (Bút Xanh) — Trưng bày cuối năm, Tiết 1"},
{"lop":1,"mon":"Mĩ thuật","tuan":34,"tiet":34,"bai":"Trưng bày sản phẩm cuối năm (Tiết 2)","yccd":"1. Năng lực mĩ thuật\n- Giới thiệu được sản phẩm mĩ thuật của mình; nêu được yếu tố tạo hình đã sử dụng.\n- Biết nhận xét, chia sẻ cảm nhận về sản phẩm của bạn.\n2. Năng lực chung\n- Giao tiếp và hợp tác: Tự tin giới thiệu, lắng nghe và nhận xét.\n- Giải quyết vấn đề và sáng tạo: Nêu cách cải tiến sản phẩm.\n3. Phẩm chất\n- Trung thực: Nhận xét khách quan, chân thành.\n- Yêu nước, nhân ái: Trân trọng sản phẩm của bạn.\n4. Tích hợp\n- Năng lực số 3.2 CB1 (Tích hợp và tinh chỉnh nội dung số): HS nhận ra sự tiến bộ của mình khi xem lại bài đầu năm và bài cuối năm.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 1; máy chiếu (nếu có); góc trưng bày đã chuẩn bị.\n- Học sinh: các sản phẩm mĩ thuật đã trưng bày.","hoatdong":[{"ten":"1. Khởi động","gv":"Mục tiêu: Tạo không khí “ngày hội mĩ thuật”.\n- GV giới thiệu buổi tham quan phòng tranh của lớp.\n- GV dẫn vào bài.","hs":"- HS lắng nghe, hào hứng.\n- HS chuẩn bị tham quan."},{"ten":"2. Khám phá - Tham quan phòng tranh","gv":"Mục tiêu: Quan sát và cảm nhận sản phẩm.\n- GV cho HS lần lượt tham quan các góc trưng bày của các nhóm.\n- GV gợi ý HS chú ý các yếu tố tạo hình đã học trong sản phẩm.","hs":"- HS tham quan các góc trưng bày.\n- HS chỉ ra chấm, nét, hình, khối, màu trong sản phẩm."},{"ten":"3. Luyện tập - Giới thiệu và nhận xét sản phẩm","gv":"Mục tiêu: Giới thiệu sản phẩm và nhận xét bài của bạn.\n- GV mời HS giới thiệu sản phẩm của mình theo câu hỏi gợi ý.\n- GV hướng dẫn HS nhận xét sản phẩm của bạn một cách chân thành, lịch sự.","hs":"- HS giới thiệu sản phẩm của mình.\n- HS nhận xét sản phẩm của bạn."},{"ten":"4. Vận dụng - Bình chọn sản phẩm em thích","gv":"Mục tiêu: Bình chọn và nêu cảm nhận.\n- GV cho HS bình chọn sản phẩm mình thích và nêu lí do.\n- GV nhận xét, khen ngợi cả lớp.","hs":"- HS bình chọn sản phẩm mình thích.\n- HS nêu lí do."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV chiếu phòng tranh của lớp gồm ảnh sản phẩm từng chủ đề xếp theo thứ tự từ đầu năm đến cuối năm; HS nhìn thấy bài đầu năm và bài cuối năm của chính mình đặt cạnh nhau nên tự nhận ra mình đã tiến bộ.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) HS chọn một sản phẩm mình thích nhất trong cả năm và nói cho cả lớp nghe vì sao mình chọn sản phẩm đó.\n⚠ (Miền 4: An toàn) Phòng tranh của lớp chỉ mở trên máy của GV và chiếu trong lớp; muốn cho ai xem ngoài lớp thì phải hỏi ý kiến các bạn có bài trong đó.","hs":"- HS nhận ra sự tiến bộ của mình khi xem lại bài đầu năm và bài cuối năm.\n- HS chọn và nói được về sản phẩm mình thích nhất trong năm."}],"status":"checked","source":"KHBD Mĩ thuật 1 KNTT (Bút Xanh) — Trưng bày cuối năm, Tiết 2"},
{"lop":1,"mon":"Mĩ thuật","tuan":35,"tiet":35,"bai":"Trưng bày sản phẩm cuối năm (Tiết 3)","yccd":"1. Năng lực mĩ thuật\n- Tự đánh giá được sự tiến bộ của bản thân qua các sản phẩm trong năm.\n- Biết giữ gìn sản phẩm và có ý thức tiếp tục sáng tạo trong hè.\n2. Năng lực chung\n- Tự chủ và tự học: Tự nhận xét sự tiến bộ của mình.\n- Giao tiếp và hợp tác: Chia sẻ dự định sáng tạo mĩ thuật trong hè.\n3. Phẩm chất\n- Chăm chỉ: Yêu thích, tiếp tục sáng tạo mĩ thuật.\n- Yêu nước: Yêu cái đẹp, yêu thiên nhiên, quê hương.\n4. Tích hợp\n- Năng lực số 3.2 CB1 (Tích hợp và tinh chỉnh nội dung số): HS xem lại nhật kí mĩ thuật của lớp và nêu được cảm nhận.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 1; máy chiếu (nếu có).\n- Học sinh: các sản phẩm mĩ thuật cả năm.","hoatdong":[{"ten":"1. Khởi động","gv":"Mục tiêu: Ôn lại hành trình học mĩ thuật cả năm.\n- GV cùng HS nhắc lại các chủ đề đã học trong năm.\n- GV dẫn vào bài tổng kết.","hs":"- HS nhắc lại các chủ đề đã học.\n- HS lắng nghe."},{"ten":"2. Khám phá - Nhìn lại sự tiến bộ của em","gv":"Mục tiêu: Tự đánh giá sự tiến bộ của bản thân.\n- GV cho HS so sánh sản phẩm đầu năm và cuối năm, hỏi: “Em thấy mình tiến bộ ở điểm nào?”\n- GV động viên, ghi nhận cố gắng của HS.","hs":"- HS so sánh và nêu điểm tiến bộ của mình.\n- HS lắng nghe."},{"ten":"3. Luyện tập - Chia sẻ sản phẩm em thích nhất","gv":"Mục tiêu: Giới thiệu sản phẩm yêu thích nhất cả năm.\n- GV mời HS giới thiệu sản phẩm mình thích nhất và lí do.\n- GV hướng dẫn HS cách cất giữ, bảo quản sản phẩm.","hs":"- HS giới thiệu sản phẩm mình thích nhất.\n- HS lắng nghe cách bảo quản sản phẩm."},{"ten":"4. Vận dụng - Dự định sáng tạo trong hè","gv":"Mục tiêu: Khơi gợi ý thức tiếp tục sáng tạo.\n- GV hỏi HS về những điều muốn vẽ, nặn, làm trong dịp hè.\n- GV tổng kết năm học, chúc HS một mùa hè vui, sáng tạo.","hs":"- HS chia sẻ dự định sáng tạo trong hè.\n- HS lắng nghe."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV chiếu lại toàn bộ phòng tranh của lớp như một cuốn nhật kí mĩ thuật và chỉ cho HS thấy mỗi bức đều có tên tác giả; GV dặn HS nhờ cha mẹ chụp lại sản phẩm ở nhà để giữ làm kỉ niệm.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) HS nói lời cảm ơn bạn đã cùng học, cùng làm sản phẩm với mình trong cả năm học.\n⚠ (Miền 4: An toàn) Muốn chụp sản phẩm ở nhà thì nhờ cha mẹ chụp giúp, HS chưa tự dùng điện thoại; ảnh sản phẩm của bạn không được tự ý gửi cho người khác.","hs":"- HS xem lại nhật kí mĩ thuật của lớp và nêu được cảm nhận.\n- HS biết cách nhờ người lớn giúp lưu giữ sản phẩm của mình."}],"status":"checked","source":"KHBD Mĩ thuật 1 KNTT (Bút Xanh) — Trưng bày cuối năm, Tiết 3"}
];
